const CEP_I18N_TEXT = {"Accueil": {"en": "Home", "pt": "Início", "ln": "Ebandeli", "sw": "Nyumbani", "lu": "Kutuadijila", "kg": "Ku Nzo"}, "Acceuil": {"en": "Home", "pt": "Início", "ln": "Ebandeli", "sw": "Nyumbani", "lu": "Kutuadijila", "kg": "Ku Nzo"}, "À Propos": {"en": "About", "pt": "Sobre", "ln": "Na ntina na biso", "sw": "Kuhusu", "lu": "Bualu bwetu", "kg": "Mu diambu dieto"}, "Qui Sommes-Nous": {"en": "Who We Are", "pt": "Quem Somos", "ln": "Biso tozali banani", "sw": "Sisi ni akina", "lu": "Tuenu badi banyi", "kg": "Beto tuena banani"}, "Horaires des cultes": {"en": "Service Times", "pt": "Horários dos Cultos", "ln": "Ngonga ya masanga", "sw": "Nyakati za ibada", "lu": "Diba dia mudimu", "kg": "Ntangu za lusambulu"}, "Je suis nouveau": {"en": "I am New", "pt": "Sou Novo", "ln": "Nazali ya sika", "sw": "Mimi ni mgeni", "lu": "Ndi mupya", "kg": "Mono ndi mfinda"}, "Parler au Pasteur": {"en": "Talk to the Pastor", "pt": "Falar com o Pastor", "ln": "Kosolola na Mokambi", "sw": "Kuzungumza na Mchungaji", "lu": "Kuakula ne Mfumu", "kg": "Solula ye Nsambi"}, "Donner ma vie à jésus": {"en": "Give My Life to Jesus", "pt": "Dar Minha Vida a Jesus", "ln": "Kopesa bomoi na ngai epai ya Yesu", "sw": "Kumpa Yesu maisha yangu", "lu": "Kupesha Yezu muoyo wanyi", "kg": "Vana luzingu luame kua Yezu"}, "Me faire baptiser": {"en": "Get Baptized", "pt": "Ser Batizado", "ln": "Kozwa libatisi", "sw": "Kubatizwa", "lu": "Kubatiza", "kg": "Botama"}, "Vie de l'église": {"en": "Church Life", "pt": "Vida da Igreja", "ln": "Bomoi ya lingomba", "sw": "Maisha ya kanisa", "lu": "Nsombelu wa dibundu", "kg": "Luzingu lua dibundu"}, "Requête de prière": {"en": "Prayer Request", "pt": "Pedido de Oração", "ln": "Bosenge ya losambo", "sw": "Ombi la maombi", "lu": "Tshilomba tshia mulombela", "kg": "Lombeli lu sambu"}, "161, Avenue de Kasa-Vubu": {"en": "161, Avenue de Kasa-Vubu", "pt": "161, Avenue de Kasa-Vubu", "ln": "161, Avenue de Kasa-Vubu", "sw": "161, Avenue de Kasa-Vubu", "lu": "161, Avenue de Kasa-Vubu", "kg": "161, Avenue de Kasa-Vubu"}, "Commune de Ngiri-Ngiri, Kinshasa": {"en": "Ngiri-Ngiri Commune, Kinshasa", "pt": "Comuna de Ngiri-Ngiri, Kinshasa", "ln": "Komini ya Ngiri-Ngiri, Kinshasa", "sw": "Manispaa ya Ngiri-Ngiri, Kinshasa", "lu": "Komini wa Ngiri-Ngiri, Kinshasa", "kg": "Komini ya Ngiri-Ngiri, Kinshasa"}, "+243 815 147 352": {"en": "+243 815 147 352", "pt": "+243 815 147 352", "ln": "+243 815 147 352", "sw": "+243 815 147 352", "lu": "+243 815 147 352", "kg": "+243 815 147 352"}, "cepberee@gmail.com": {"en": "cepberee@gmail.com", "pt": "cepberee@gmail.com", "ln": "cepberee@gmail.com", "sw": "cepberee@gmail.com", "lu": "cepberee@gmail.com", "kg": "cepberee@gmail.com"}, "Bienvenue à Berée": {"en": "Welcome to Berea", "pt": "Bem-vindo a Bereia", "ln": "Boyei bolamu na Berée", "sw": "Karibu Berea", "lu": "Buakuidi ku Berée", "kg": "Vwakana kuna Berée"}, "« Le Centre Évangélique Pentecôtiste Berée est une église locale de la 37ème communauté des ensemblées de Dieu du Congo... »": {"en": "\"The Berea Pentecostal Evangelical Center is a local church of the 37th Assemblies of God Community of Congo...\"", "pt": "\"O Centro Evangélico Pentecostal Bereia é uma igreja local da 37ª Comunidade das Assembleias de Deus do Congo...\"", "ln": "« Lingomba ya CEP Berée ezali lingomba ya mboka ya Communauté ya 37 ya Assemblées de Dieu ya Congo... »", "sw": "\"Kanisa la CEP Berée ni kanisa la mtaa la Jumuiya ya 37 ya Mikutano ya Mungu ya Kongo...\"", "lu": "« Dibundu dia CEP Berée didi dibundu dia muaba dia Tshisumbu tshia 37 tshia Bisumbu bia Nzambi bia Kongo... »", "kg": "« Dibundu dia CEP Berée didi dibundu dia zunga kia Kimvuka kia 37 kia Zindongi za Nzambi za Kongo... »"}, "Rejoignez-nous": {"en": "Join Us", "pt": "Junte-se a Nós", "ln": "Sangana na biso", "sw": "Jiunge nasi", "lu": "Wisangana netu", "kg": "Kutakana yeto"}, "Notre histoire": {"en": "Our Story", "pt": "Nossa História", "ln": "Lisolo na biso", "sw": "Historia yetu", "lu": "Muanda wetu", "kg": "Mbandu yeto"}, "Tu n'es pas ici par hasard !": {"en": "You Are Not Here by Chance!", "pt": "Você Não Está Aqui por Acaso!", "ln": "Oyei awa na ntembe te !", "sw": "Haupo hapa kwa bahati mbaya!", "lu": "Wewi kuaku kabiyi bua diakanyi to !", "kg": "Wena vava ku diambu ko !"}, "Découvrez notre église et comment nous rejoindre pour la première fois.": {"en": "Discover our church and how to join us for the first time.", "pt": "Descubra nossa igreja e como se juntar a nós pela primeira vez.", "ln": "Yeba lingomba na biso mpe ndenge ya kosangana na biso mbala ya liboso.", "sw": "Gundua kanisa letu na jinsi ya kujiunga nasi kwa mara ya kwanza.", "lu": "Manya dibundu dietu ne mushindu wa kudisangisha netu bua musangu wa kumpala.", "kg": "Zaba dibundu dieto ye phila ya kukutakana yeto lubila kiantete."}, "En savoir plus →": {"en": "Learn more →", "pt": "Saiba mais →", "ln": "Yeba mingi →", "sw": "Jifunze zaidi →", "lu": "Manya bikole →", "kg": "Zaba malembi →"}, "Parler au pasteur": {"en": "Talk to the Pastor", "pt": "Falar com o Pastor", "ln": "Kosolola na mokambi", "sw": "Kuzungumza na mchungaji", "lu": "Kuakula ne mfumu", "kg": "Solula ye nsambi"}, "Besoin d'un conseil spirituel ou d'un accompagnement personnel ? Contactez-nous.": {"en": "Need spiritual advice or personal support? Contact us.", "pt": "Precisa de conselho espiritual ou acompanhamento pessoal? Contate-nos.", "ln": "Ozali na mposa ya toli ya molimo to ya lisungi ya moto na moto ? Bimela biso.", "sw": "Unahitaji ushauri wa kiroho au msaada wa kibinafsi? Wasiliana nasi.", "lu": "Udi né dijinga dia mibelu ya mu nyuma anyi diambuluisha? Wakule netu.", "kg": "Wena mfunu wa lusadusu lua mu mpeve voti lusadusu lua mutindu? Solula yeto."}, "Prendre contact →": {"en": "Get in touch →", "pt": "Entre em contato →", "ln": "Kokutana →", "sw": "Wasiliana →", "lu": "Wakule →", "kg": "Solula →"}, "Donner ma vie à Jésus": {"en": "Give My Life to Jesus", "pt": "Dar Minha Vida a Jesus", "ln": "Kopesa bomoi na ngai epai ya Yesu", "sw": "Kumpa Yesu maisha yangu", "lu": "Kupesha Yezu muoyo wanyi", "kg": "Vana luzingu luame kua Yezu"}, "Faites le pas le plus important de votre vie et commencez un nouveau chemin avec Christ.": {"en": "Take the most important step of your life and begin a new path with Christ.", "pt": "Dê o passo mais importante da sua vida e comece um novo caminho com Cristo.", "ln": "Sala litambe ya ntina mingi na bomoi na yo mpe banda nzela ya sika elongo na Klisto.", "sw": "Chukua hatua muhimu zaidi ya maisha yako na anza njia mpya na Kristo.", "lu": "Enza tshishishi tshinene tshia muoyo webe ne utuadije njila mupya ne Kristo.", "kg": "Sala kima kianene kia luzingu luaku ye yantika nzila yampa ye Kristu."}, "Faire ce pas →": {"en": "Take this step →", "pt": "Dar este passo →", "ln": "Sala litambe oyo →", "sw": "Chukua hatua hii →", "lu": "Enza tshishishi etshi →", "kg": "Sala mambu mama →"}, "Le baptême est une étape essentielle dans votre marche avec Dieu. Inscrivez-vous.": {"en": "Baptism is an essential step in your walk with God. Sign up.", "pt": "O batismo é uma etapa essencial na sua caminhada com Deus. Inscreva-se.", "ln": "Libatisi ezali litambe ya ntina mingi na botamboli na yo elongo na Nzambe. Komisa nkombo na yo.", "sw": "Ubatizo ni hatua muhimu katika mwenendo wako na Mungu. Jisajili.", "lu": "Dibatiza didi tshishishi tshinene mu njila webe ne Nzambi. Difundisha dîna diebe.", "kg": "Botama i kima kianene mu nzila aku ye Nzambi. Sonika zina kiaku."}, "M'inscrire →": {"en": "Sign up →", "pt": "Inscrever-se →", "ln": "Komisa nkombo na ngai →", "sw": "Jisajili →", "lu": "Difundisha dîna →", "kg": "Sonika zina →"}, "Actualités": {"en": "News", "pt": "Notícias", "ln": "Basango", "sw": "Habari", "lu": "Malu mapya", "kg": "Nsangu"}, "À la une": {"en": "Featured", "pt": "Destaques", "ln": "Oyo ezali sika", "sw": "Habari kuu", "lu": "Malu ma kumpala", "kg": "Nsangu za kimfumu"}, "YouTube": {"en": "YouTube", "pt": "YouTube", "ln": "YouTube", "sw": "YouTube", "lu": "YouTube", "kg": "YouTube"}, "Facebook": {"en": "Facebook", "pt": "Facebook", "ln": "Facebook", "sw": "Facebook", "lu": "Facebook", "kg": "Facebook"}, "Impossible de charger le contenu. Vérifiez vos clés API.": {"en": "Unable to load content. Check your API keys.", "pt": "Não foi possível carregar o conteúdo. Verifique suas chaves de API.", "ln": "Ekoki te kotia makambo. Tala bafungola na yo ya API.", "sw": "Imeshindwa kupakia maudhui. Angalia funguo zako za API.", "lu": "Kabiyi mua kutuma bualu. Tangila bikuku biebe bia API.", "kg": "Ka lulendo ko mu kotisa. Tala zisabi za nge za API."}, "Notre Histoire & Qui Sommes-Nous": {"en": "Our History & Who We Are", "pt": "Nossa História e Quem Somos", "ln": "Lisolo na biso & Biso tozali banani", "sw": "Historia Yetu na Sisi ni Akina", "lu": "Muanda wetu ne Tuenu Badi Banyi", "kg": "Mbandu Yeto ye Beto Tuena Banani"}, "Rév. Pasteur TSHISUNGU MWAMBI": {"en": "Rev. Pastor TSHISUNGU MWAMBI", "pt": "Rev. Pastor TSHISUNGU MWAMBI", "ln": "Mokambi TSHISUNGU MWAMBI", "sw": "Mchungaji TSHISUNGU MWAMBI", "lu": "Mfumu TSHISUNGU MWAMBI", "kg": "Nsambi TSHISUNGU MWAMBI"}, "Fondateur · 1983": {"en": "Founder · 1983", "pt": "Fundador · 1983", "ln": "Mobandisi · 1983", "sw": "Mwanzilishi · 1983", "lu": "Mubadishi · 1983", "kg": "Nkuni · 1983"}, "Pasteur IYELI BAHENDE Elie": {"en": "Pastor IYELI BAHENDE Elie", "pt": "Pastor IYELI BAHENDE Elie", "ln": "Mokambi IYELI BAHENDE Elie", "sw": "Mchungaji IYELI BAHENDE Elie", "lu": "Mfumu IYELI BAHENDE Elie", "kg": "Nsambi IYELI BAHENDE Elie"}, "Pasteur Titulaire": {"en": "Senior Pastor", "pt": "Pastor Titular", "ln": "Mokambi Mokonzi", "sw": "Mchungaji Mkuu", "lu": "Mfumu Munene", "kg": "Nsambi Munene"}, "Fondé par le Révérend Pasteur": {"en": "Founded by Reverend Pastor", "pt": "Fundado pelo Reverendo Pastor", "ln": "Ebandisamaki na Mokambi Mokonzi", "sw": "Ilianzishwa na Mchungaji Mtukufu", "lu": "Wakabuluwa kudi Mfumu Mutumibua", "kg": "Wavangama kua Nsambi"}, "TSHISUNGU MWAMBI": {"en": "TSHISUNGU MWAMBI", "pt": "TSHISUNGU MWAMBI", "ln": "TSHISUNGU MWAMBI", "sw": "TSHISUNGU MWAMBI", "lu": "TSHISUNGU MWAMBI", "kg": "TSHISUNGU MWAMBI"}, "en 1983 et dirigé aujourd'hui avec consécration par le Pasteur": {"en": "in 1983 and led today with devotion by Pastor", "pt": "em 1983 e liderado hoje com dedicação pelo Pastor", "ln": "na mobu 1983 mpe ekambami lelo na komipesa na Mokambi", "sw": "mwaka 1983 na kuongozwa leo kwa juhudi na Mchungaji", "lu": "mu 1983 ne kulombolwa lelu ne dijinga kudi Mfumu", "kg": "mu 1983 ye lombolwa lelu kua Nsambi"}, "IYELI BAHENDE Elie": {"en": "IYELI BAHENDE Elie", "pt": "IYELI BAHENDE Elie", "ln": "IYELI BAHENDE Elie", "sw": "IYELI BAHENDE Elie", "lu": "IYELI BAHENDE Elie", "kg": "IYELI BAHENDE Elie"}, ", le Centre Évangélique Pentecôtiste Bérée a grandi au fil des années pour devenir une communauté vivante, chaleureuse et enracinée dans la Parole de Dieu.": {"en": ", the Berea Pentecostal Evangelical Center has grown over the years into a living, warm community rooted in the Word of God.", "pt": ", o Centro Evangélico Pentecostal Bereia cresceu ao longo dos anos até se tornar uma comunidade viva, calorosa e enraizada na Palavra de Deus.", "ln": ", Centre Évangélique Pentecôtiste Bérée ekoli na boumeli ya bambula mpo ekoma lisanga ya bomoi, ya bolingo, mpe ya misisa na Liloba ya Nzambe.", "sw": ", Kituo cha Kiinjili cha Kipentekoste cha Berea kimekua kwa miaka mingi na kuwa jumuiya hai, yenye ukarimu na iliyojikita katika Neno la Mungu.", "lu": ", Tshibutu tshia Evanjeliyo tshia Pantekoti tshia Bérée tshakuluka mu bidimu bia bungi bua kuikala tshisumbu tshia muoyo, tshidi tshianga ne tshijadikile mu Dîyi dia Nzambi.", "kg": ", Kimvuka kia Evanjelu kia Pantekoti kia Bérée kiakula mu mimvu miayingi mu diambu dia kituka dibundu diamoyo, dia luzolo ye dijikama mu Diambu dia Nzambi."}, "En tant qu'église locale de la": {"en": "As a local church of the", "pt": "Como igreja local da", "ln": "Lokola lingomba ya mboka ya", "sw": "Kama kanisa la mtaa la", "lu": "Bu dibundu dia muaba dia", "kg": "Bu dibundu kia zunga kia"}, "37ème Communauté des Assemblées de Dieu du Congo (C.A.D.C)": {"en": "37th Assemblies of God Community of Congo (C.A.D.C)", "pt": "37ª Comunidade das Assembleias de Deus do Congo (C.A.D.C)", "ln": "Communauté ya 37 ya Assemblées de Dieu ya Congo (C.A.D.C)", "sw": "Jumuiya ya 37 ya Mikutano ya Mungu ya Kongo (C.A.D.C)", "lu": "Tshisumbu tshia 37 tshia Bisumbu bia Nzambi bia Kongo (C.A.D.C)", "kg": "Kimvuka kia 37 kia Zindongi za Nzambi za Kongo (C.A.D.C)"}, ", et inspirés par l'attitude des chrétiens de Bérée (Actes 17:11), nous avons à cœur d'étudier les Écritures avec zèle et de vivre une foi authentique. Notre communauté se veut un refuge de paix, un lieu de restauration et une famille spirituelle pour quiconque cherche à s'approcher de Dieu.": {"en": ", and inspired by the attitude of the Bereans (Acts 17:11), we are devoted to studying the Scriptures with zeal and living an authentic faith. Our community aims to be a refuge of peace, a place of restoration, and a spiritual family for anyone seeking to draw near to God.", "pt": ", e inspirados pela atitude dos crentes de Bereia (Atos 17:11), temos o compromisso de estudar as Escrituras com zelo e viver uma fé autêntica. Nossa comunidade quer ser um refúgio de paz, um lugar de restauração e uma família espiritual para quem busca se aproximar de Deus.", "ln": ", mpe na kolendisama na ezaleli ya bandimi ya Bérée (Misala 17:11), tozali na mposa ya koyekola Makomi na molende mpe kobika kondima ya solo. Lisanga na biso elingi ezala esika ya kimia, esika ya kozongisama, mpe libota ya molimo mpo na moto nyonso oyo alukaka kopusana pene na Nzambe.", "sw": ", na tukiongozwa na mfano wa waumini wa Berea (Matendo 17:11), tunajitolea kuchunguza Maandiko kwa bidii na kuishi imani ya kweli. Jumuiya yetu inataka kuwa kimbilio la amani, mahali pa kurejeshwa, na familia ya kiroho kwa yeyote anayetafuta kumkaribia Mungu.", "lu": ", ne kulomba kudi tshikeelekelu tshia bena Bérée (Bienzedi 17:11), tudi ne dijinga dia kulonga Mukanda wa Nzambi ne bujitu ne kuikala ne ditabuja dilelela. Tshisumbu tshietu tshidi tshijinga kuikala muaba wa ditalala, muaba wa kuvuija, ne dîku dia mu nyuma bua muntu yonso udi ukeba bua kusemena ku Nzambi.", "kg": ", ye mu simina bikuluntu bia bakristu ba Bérée (Bisalu 17:11), tuena ye luzolo lua kulonguka Masonuku ye bunkufi ye zinga minu ya kieleka. Kimvuka kieto kizolele kuikala fulu kia ngemba, fulu kia vutukusu, ye dibuta dia mu mpeve mu diambu dia konso muntu wunlombanga kufinama Nzambi."}, "Conscient des défis de notre époque, le CEP Bérée dépasse les murs de son bâtiment. Nous œuvrons activement sur les réseaux sociaux et le digital pour propager l'Évangile de Jésus-Christ au-delà des frontières. À travers nos partages, nos vidéos et nos temps de prière en ligne, nous voulons apporter l'espérance et la lumière du Christ directement dans votre quotidien.": {"en": "Aware of the challenges of our time, CEP Bérée reaches beyond the walls of its building. We are actively engaged on social media and digital platforms to spread the Gospel of Jesus Christ beyond borders. Through our posts, videos, and online prayer times, we want to bring the hope and light of Christ directly into your daily life.", "pt": "Conscientes dos desafios da nossa época, o CEP Bereia vai além das paredes do seu edifício. Trabalhamos ativamente nas redes sociais e no digital para propagar o Evangelho de Jesus Cristo além das fronteiras. Através das nossas partilhas, vídeos e momentos de oração online, queremos levar a esperança e a luz de Cristo diretamente ao seu dia a dia.", "ln": "Lokola toyebi mikakatano ya ntango na biso, CEP Bérée ekatisi bamir ya ndako na yango. Tosalaka makasi na ba réseaux sociaux mpe na internet mpo na kopalanganisa Nsango Malamu ya Yesu-Klisto libanda ya bandelo. Na nzela ya biteni na biso, ba vidéo na biso mpe bantango na biso ya losambo na internet, tolingi komema elikya mpe pole ya Klisto na bomoi na yo ya mokolo na mokolo.", "sw": "Tukiwa na uelewa wa changamoto za wakati wetu, CEP Bérée inavuka kuta za jengo lake. Tunafanya kazi kwa bidii kwenye mitandao ya kijamii na kidijitali kueneza Injili ya Yesu Kristo zaidi ya mipaka. Kupitia machapisho yetu, video zetu na nyakati zetu za maombi mtandaoni, tunataka kuleta tumaini na nuru ya Kristo moja kwa moja katika maisha yako ya kila siku.", "lu": "Bu tudi bamanye ntatu ya tshikondi tshietu, CEP Bérée idi ipita ku miba ya nzubu wende. Tudi tuenza mudimu ne dijinga pa réseaux sociaux ne pa internet bua kutangalaja Lumu Luimpe lua Yezu-Kristo kupita miaba yonso. Ku diambu dia bimfundu bietu, bidimu bietu, ne bikondi bietu bia mulombela pa internet, tudi tujinga kuleja ditekemena ne butoke bua Kristo mu muoyo webe wa dituku ne dituku.", "kg": "Bu tuzabi ntantu ya ntangu yeto, CEP Bérée ilenda kabuka mimbu ya nzo andi. Tuena sala ye ngolo pa réseaux sociaux ye pa internet mu tangalasa Nsangu Zambote za Yezu-Kristu kuluta ndilu. Mu bikubu bieto, bimwaneka bieto ye ntangu zeto za sambu pa internet, tuzolele natina ditekemena ye kia Kristu mu luzingu luaku lua konso lumbu."}, "« Examinez toutes choses ; retenez ce qui est bon. » —": {"en": "\"Test everything; hold on to what is good.\" —", "pt": "\"Examinai tudo; retende o que é bom.\" —", "ln": "« Botala makambo nyonso ; bobatela oyo ezali malamu. » —", "sw": "\"Jaribuni kila kitu; shikamaneni na kilicho chema.\" —", "lu": "« Konkonona bintu bionso; ulame tshidi tshimpe. » —", "kg": "« Fionguna mambu moso; simba diambu dimboti. » —"}, "1 Thessaloniciens 5:21": {"en": "1 Thessalonians 5:21", "pt": "1 Tessalonicenses 5:21", "ln": "1 Batesalonika 5:21", "sw": "1 Wathesalonike 5:21", "lu": "1 Tesalonika 5:21", "kg": "1 Tesalonika 5:21"}, "Notre Vision & Nos Piliers": {"en": "Our Vision & Our Pillars", "pt": "Nossa Visão e Nossos Pilares", "ln": "Emonaneli na biso & Makonzi na biso", "sw": "Maono Yetu na Nguzo Zetu", "lu": "Tshimoneke tshietu ne Bikuatshilu bietu", "kg": "Mona kieto ye Mabaya meto"}, "Une communauté fondée sur les Écritures": {"en": "A Community Founded on the Scriptures", "pt": "Uma Comunidade Fundada nas Escrituras", "ln": "Lisanga oyo etongami na Makomi", "sw": "Jumuiya Iliyojengwa juu ya Maandiko", "lu": "Tshisumbu tshidibakidibue pa Mukanda wa Nzambi", "kg": "Kimvuka Kivangama pa Masonuku"}, "Nous sommes une communauté chrétienne enracinée dans la Parole de Dieu, engagée à vivre une foi authentique qui transforme les vies et influence positivement notre société. Notre vision et nos actions s'articulent autour de trois axes fondamentaux qui guident notre mission et notre engagement au quotidien :": {"en": "We are a Christian community rooted in the Word of God, committed to living an authentic faith that transforms lives and positively influences our society. Our vision and actions revolve around three fundamental pillars that guide our mission and daily commitment:", "pt": "Somos uma comunidade cristã enraizada na Palavra de Deus, comprometida a viver uma fé autêntica que transforma vidas e influencia positivamente a nossa sociedade. Nossa visão e ações giram em torno de três eixos fundamentais que orientam nossa missão e nosso compromisso diário:", "ln": "Tozali lisanga ya baklisto oyo ezali na misisa na Liloba ya Nzambe, oyo emipesi na kobika kondima ya solo oyo ebongolaka bomoi mpe etindaka na ndenge ya malamu lingomba na biso. Emonaneli na biso mpe misala na biso etongami likolo ya makonzi misato ya ntina oyo ekambaka mokumba na biso mikolo nyonso :", "sw": "Sisi ni jumuiya ya Kikristo iliyojikita katika Neno la Mungu, iliyojitolea kuishi imani ya kweli inayobadilisha maisha na kuathiri vyema jamii yetu. Maono na matendo yetu yanajikita katika nguzo tatu za msingi zinazoongoza dhamira yetu na ahadi yetu ya kila siku:", "lu": "Tudi tshisumbu tshia bena Kristo tshidi tshijadikile mu Dîyi dia Nzambi, tshidi tshidipeshe bua kuenza ditabuja dilelela didi diakulula mioyo ne diambuluisha tshisamba tshietu bimpe. Tshimoneke tshietu ne bienzedi bietu bidi bijadike pa bikuatshilu bisatu bidi bilombola mudimu wetu ne dijinga dietu dia dituku ne dituku :", "kg": "Tuena kimvuka kia bakristu kidi kijikama mu Diambu dia Nzambi, kidi kidipesa mu zinga minu ya kieleka yinsobisanga zinga ye kuvua nsi eto malandu mambote. Mona kieto ye mavanga meto madi majikama pa mabaya matatu malombolanga mfulu eto ye luzolo lweto lua konso lumbu :"}, "Des cultes dynamiques": {"en": "Dynamic Worship Services", "pt": "Cultos Dinâmicos", "ln": "Masanga ya bomoi", "sw": "Ibada za Kiuchangamfu", "lu": "Bisumbu bia Muoyo", "kg": "Lusambulu lua Ngolo"}, "Des moments de louange vibrants et d'adoration intense où la présence du Saint-Esprit est honorée et célébrée.": {"en": "Vibrant moments of praise and intense worship where the presence of the Holy Spirit is honored and celebrated.", "pt": "Momentos vibrantes de louvor e adoração intensa onde a presença do Espírito Santo é honrada e celebrada.", "ln": "Bantango ya lisanzoli ya makasi mpe ya losambo ya bozindo esika bozali ya Molimo Mosantu ekumisami mpe esepelami.", "sw": "Nyakati za sifa hai na ibada kubwa ambapo uwepo wa Roho Mtakatifu unaheshimiwa na kusherehekewa.", "lu": "Bikondi bia disanka dia bukole ne mulombela wa bunene mudi lupetu lua Nyuma Muyilu lutumbula ne lusanka.", "kg": "Ntangu za nzitusu ye lusambulu lua ngolo muna nzailu ya Mpeve Yanlongo yinzitusu ye yisepelesa."}, "Des enseignements profonds": {"en": "Profound Teachings", "pt": "Ensinamentos Profundos", "ln": "Mateya ya bozindo", "sw": "Mafundisho ya Kina", "lu": "Malongesha manene", "kg": "Malongi manene"}, "Une prédication fidèle à la Parole de Dieu, pratique et accessible, pour équiper chaque croyant dans sa marche quotidienne (Foi ancrée dans la Parole).": {"en": "Preaching faithful to the Word of God, practical and accessible, to equip every believer in their daily walk (Faith rooted in the Word).", "pt": "Uma pregação fiel à Palavra de Deus, prática e acessível, para equipar cada crente em sua caminhada diária (Fé enraizada na Palavra).", "ln": "Mateya oyo ezali sembo na Liloba ya Nzambe, ya pratike mpe ya pete, mpo na kobongisa mondimi nyonso na botamboli na ye ya mokolo na mokolo (Kondima ekangami na Liloba).", "sw": "Mahubiri yanayoshikamana na Neno la Mungu, ya vitendo na rahisi kufikiwa, kuandaa kila muumini katika mwenendo wake wa kila siku (Imani iliyojikita katika Neno).", "lu": "Malongesha adi ne bushuwa bua Dîyi dia Nzambi, madi mua kuenza ne mepepele bua kulongesha muena kuitabuja yonso mu njila wende wa dituku ne dituku (Ditabuja dijadikile mu Dîyi).", "kg": "Malongi ma kieleka mu Diambu dia Nzambi, mamboti ye maswaswa, mu kubongesa konso nkwikizi mu nzila andi ya konso lumbu (Minu kijikama mu Diambu)."}, "Des moments intenses de prière": {"en": "Intense Moments of Prayer", "pt": "Momentos Intensos de Oração", "ln": "Bantango ya makasi ya losambo", "sw": "Nyakati za Maombi Makali", "lu": "Bikondi bia mulombela munene", "kg": "Ntangu za sambu ya ngolo"}, "Parce que la prière est le moteur de notre foi, nous élevons nos voix ensemble pour intercéder, briser les chaînes et voir la main de Dieu agir au service de sa Mission.": {"en": "Because prayer is the driving force of our faith, we raise our voices together to intercede, break chains, and see God's hand at work in service of His Mission.", "pt": "Porque a oração é o motor da nossa fé, elevamos nossas vozes juntos para interceder, quebrar correntes e ver a mão de Deus agir a serviço de Sua Missão.", "ln": "Lokola losambo ezali motuya ya kondima na biso, totombolaka mingongo na biso esika moko mpo na kobondela, kobuka minyololo, mpe komona loboko ya Nzambe kosala mpo na Mokumba na Ye.", "sw": "Kwa sababu maombi ni injini ya imani yetu, tunainua sauti zetu pamoja kuombea, kuvunja minyororo, na kuona mkono wa Mungu ukitenda kazi katika huduma ya Utume wake.", "lu": "Bu mulombela mmona wa ditabuja dietu, tudi tubandisha diyi dietu pamue bua kulombela bua bakuabu, kutshibula nkanu, ne kumona tshianza tshia Nzambi tshienza mudimu bua Mudimu wende.", "kg": "Mu diambu sambu i mona ya minu kieto, tuena vumuna ndinga zeto va kimosi mu lombela, kasuka nsinga, ye mona koko kua Nzambi kisala mu kisalu kia Mfulu andi."}, "Rejoignez-nous !": {"en": "Join Us!", "pt": "Junte-se a Nós!", "ln": "Sangana na biso !", "sw": "Jiunge Nasi!", "lu": "Wisangana Netu !", "kg": "Kutakana Yeto !"}, "Que vous soyez en quête de réponses spirituelles, de passage dans la région, ou à la recherche d'une communauté fraternelle pour grandir dans la grâce, vous êtes les bienvenus au CEP Bérée. Venez vivre avec nous des moments uniques de rafraîchissement spirituel.": {"en": "Whether you are seeking spiritual answers, just passing through the region, or looking for a fellowship community to grow in grace, you are welcome at CEP Bérée. Come and experience unique moments of spiritual refreshment with us.", "pt": "Quer você esteja em busca de respostas espirituais, de passagem pela região, ou à procura de uma comunidade fraterna para crescer na graça, você é bem-vindo ao CEP Bereia. Venha viver conosco momentos únicos de refrigério espiritual.", "ln": "Ezala ozali koluka biyano ya molimo, ozali kaka koleka na etuka, to ozali koluka lisanga ya bondeko mpo na kokola na ngolu, oyaka malamu na CEP Bérée. Yaka kobika elongo na biso bantango ya sika ya kopema ya molimo.", "sw": "Iwe unatafuta majibu ya kiroho, unapitia tu eneo hili, au unatafuta jumuiya ya udugu ili kukua katika neema, unakaribishwa katika CEP Bérée. Njoo uishi nasi nyakati za kipekee za uburudisho wa kiroho.", "lu": "Nansha wewi ukeba mandamuna a mu nyuma, wewi upita anu mu tshimenga etshi, anyi ukeba tshisumbu tshia buakuidi bua kukola mu ngasa, udi muakuidibue ku CEP Bérée. Luaku tunombole nabu bikondi bipiabipia bia disanka dia mu nyuma.", "kg": "Ka bu wena tomba mvutu za mu mpeve, wena kaka viokila mu zunga, voti wena tomba kimvuka kia kimpangi mu diambu dia yela mu nlemvo, wena vwakana kuna CEP Bérée. Yiza zinga yeto ntangu za kaka za luvutulu lua mu mpeve."}, "Jésus-Christ vous aime, et nous aussi !": {"en": "Jesus Christ loves you, and so do we!", "pt": "Jesus Cristo ama você, e nós também!", "ln": "Yesu-Klisto alingaka yo, mpe biso mpe !", "sw": "Yesu Kristo anakupenda, na sisi pia!", "lu": "Yezu-Kristo unakusua, ne tuetu petu!", "kg": "Yezu-Kristu wukuzolele, ye beto mpe!"}, "Cultes & Réunions": {"en": "Services & Meetings", "pt": "Cultos e Reuniões", "ln": "Masanga & Makita", "sw": "Ibada na Mikutano", "lu": "Bisumbu ne Bisangilu", "kg": "Lusambulu ye Zindongi"}, "Portes ouvertes pour tous": {"en": "Open Doors for All", "pt": "Portas Abertas para Todos", "ln": "Bikuke efungwami mpo na bato nyonso", "sw": "Milango Wazi kwa Wote", "lu": "Bibuebue Bidibuluke bua bantu bonso", "kg": "Mielo Mizibuka mu Batu Boso"}, "Nous vous accueillons chaleureusement, que vous soyez croyant de longue date ou simplement curieux de découvrir la foi chrétienne. Tous sont les bienvenus ici.": {"en": "We welcome you warmly, whether you are a long-time believer or simply curious to discover the Christian faith. Everyone is welcome here.", "pt": "Nós o recebemos calorosamente, seja você um crente de longa data ou apenas curioso para descobrir a fé cristã. Todos são bem-vindos aqui.", "ln": "Toyambi bino na bolingo, ezala bozali bandimi ya kala to bozali kaka na mposa ya koyeba kondima ya boklisto. Bato nyonso bayambami awa.", "sw": "Tunakukaribisha kwa uchangamfu, iwe ni muumini wa muda mrefu au unatamani tu kugundua imani ya Kikristo. Kila mtu anakaribishwa hapa.", "lu": "Tudi tuakidila ne dianga, nansha wewi mmuena kuitabuja wa kale anyi udi anu ne dijinga dia kumanya ditabuja dia bena Kristo. Bantu bonso badi bakidibue kunku.", "kg": "Tuena kuakisa aku ye luzolo, ka bu wena nkwikizi wa ntama voti wena kaka luzolo lua zaba minu kia bakristu. Batu boso bavwakana vava."}, "Planifier une visite": {"en": "Plan a Visit", "pt": "Planejar uma Visita", "ln": "Kobongisa kotala biso", "sw": "Panga Ziara", "lu": "Longesha bukezuku", "kg": "Vanga nkumbu"}, "Lundi au Vendredi": {"en": "Monday to Friday", "pt": "Segunda a Sexta", "ln": "Mokolo mibale kino mokolo mitano", "sw": "Jumatatu hadi Ijumaa", "lu": "Mionso ya lundi too ne vendredi", "kg": "Nsona too na lumingu"}, "Culte matinal": {"en": "Morning Service", "pt": "Culto Matinal", "ln": "Losambo ya ntongo", "sw": "Ibada ya Asubuhi", "lu": "Mulombela wa dinda", "kg": "Lusambulu lua nsuka"}, "06h00 – 07h00": {"en": "6:00 AM – 7:00 AM", "pt": "06h00 – 07h00", "ln": "06h00 – 07h00", "sw": "Saa 12:00 – 1:00 asubuhi", "lu": "06h00 – 07h00", "kg": "06h00 – 07h00"}, "Mardi et Jeudi": {"en": "Tuesday and Thursday", "pt": "Terça e Quinta", "ln": "Mokolo ya misato mpe mokolo ya minei", "sw": "Jumanne na Alhamisi", "lu": "Mardi ne Jeudi", "kg": "Nzoono ye nkази"}, "Enseignement": {"en": "Teaching", "pt": "Ensino", "ln": "Mateya", "sw": "Mafundisho", "lu": "Malongesha", "kg": "Malongi"}, "17h00 – 19h00": {"en": "5:00 PM – 7:00 PM", "pt": "17h00 – 19h00", "ln": "17h00 – 19h00", "sw": "Saa 11:00 – 1:00 jioni", "lu": "17h00 – 19h00", "kg": "17h00 – 19h00"}, "Mercredi": {"en": "Wednesday", "pt": "Quarta-feira", "ln": "Mokolo ya misato", "sw": "Jumatano", "lu": "Mercredi", "kg": "Nkia"}, "Réunion des femmes": {"en": "Women's Meeting", "pt": "Reunião das Mulheres", "ln": "Likita ya basi", "sw": "Mkutano wa Wanawake", "lu": "Disangisha dia bakaji", "kg": "Lukutakanu lua bakento"}, "08h00 – 10h30": {"en": "8:00 AM – 10:30 AM", "pt": "08h00 – 10h30", "ln": "08h00 – 10h30", "sw": "Saa 2:00 – 4:30 asubuhi", "lu": "08h00 – 10h30", "kg": "08h00 – 10h30"}, "Samedi": {"en": "Saturday", "pt": "Sábado", "ln": "Mposo", "sw": "Jumamosi", "lu": "Samedi", "kg": "Nsabala"}, "Réunion des jeunes": {"en": "Youth Meeting", "pt": "Reunião dos Jovens", "ln": "Likita ya bilenge", "sw": "Mkutano wa Vijana", "lu": "Disangisha dia bansonga", "kg": "Lukutakanu lua matoko"}, "Dimanche": {"en": "Sunday", "pt": "Domingo", "ln": "Eyenga", "sw": "Jumapili", "lu": "Dimanche", "kg": "Lumingu"}, "École de Dimanche": {"en": "Sunday School", "pt": "Escola Dominical", "ln": "Kelasi ya Eyenga", "sw": "Shule ya Jumapili", "lu": "Tshikolo tshia Dimanche", "kg": "Nkangu ya lumingu"}, "09h00 – 11h00": {"en": "9:00 AM – 11:00 AM", "pt": "09h00 – 11h00", "ln": "09h00 – 11h00", "sw": "Saa 3:00 – 5:00 asubuhi", "lu": "09h00 – 11h00", "kg": "09h00 – 11h00"}, "Culte Dominical": {"en": "Sunday Service", "pt": "Culto Dominical", "ln": "Losambo ya Eyenga", "sw": "Ibada ya Jumapili", "lu": "Mulombela wa Dimanche", "kg": "Lusambulu lua Lumingu"}, "08h00 – 11h00": {"en": "8:00 AM – 11:00 AM", "pt": "08h00 – 11h00", "ln": "08h00 – 11h00", "sw": "Saa 2:00 – 5:00 asubuhi", "lu": "08h00 – 11h00", "kg": "08h00 – 11h00"}, "Nous Contacter": {"en": "Contact Us", "pt": "Contate-nos", "ln": "Bimela biso", "sw": "Wasiliana Nasi", "lu": "Wakule netu", "kg": "Solula yeto"}, "Venez comme vous êtes": {"en": "Come As You Are", "pt": "Venha Como Você É", "ln": "Yaka ndenge ozali", "sw": "Njoo Ulivyo", "lu": "Luaku bu udi", "kg": "Yiza bu wena"}, "Adresse": {"en": "Address", "pt": "Endereço", "ln": "Adrese", "sw": "Anwani", "lu": "Aderese", "kg": "Kisala"}, "Téléphone": {"en": "Phone", "pt": "Telefone", "ln": "Telefone", "sw": "Simu", "lu": "Telefone", "kg": "Foni"}, "Email": {"en": "Email", "pt": "Email", "ln": "Email", "sw": "Barua pepe", "lu": "Email", "kg": "Email"}, "Prénom": {"en": "First Name", "pt": "Primeiro Nome", "ln": "Kombo ya liboso", "sw": "Jina la Kwanza", "lu": "Dîna dia kumpala", "kg": "Zina kiantete"}, "Nom": {"en": "Last Name", "pt": "Sobrenome", "ln": "Kombo ya libota", "sw": "Jina la Ukoo", "lu": "Dîna dia dîku", "kg": "Zina kia dikanda"}, "Téléphone *": {"en": "Phone *", "pt": "Telefone *", "ln": "Telefone *", "sw": "Simu *", "lu": "Telefone *", "kg": "Foni *"}, "Message": {"en": "Message", "pt": "Mensagem", "ln": "Nsango", "sw": "Ujumbe", "lu": "Lumu", "kg": "Nsamu"}, "Envoyer le message": {"en": "Send Message", "pt": "Enviar Mensagem", "ln": "Kotinda nsango", "sw": "Tuma Ujumbe", "lu": "Tuma lumu", "kg": "Fidisa nsamu"}, "Centre Évangélique Pentecôtiste Berée": {"en": "Berea Pentecostal Evangelical Center", "pt": "Centro Evangélico Pentecostal Bereia", "ln": "Centre Évangélique Pentecôtiste Berée", "sw": "Kituo cha Kiinjili cha Kipentekoste cha Berea", "lu": "Tshibutu tshia Evanjeliyo tshia Pantekoti tshia Bérée", "kg": "Kimvuka kia Evanjelu kia Pantekoti kia Bérée"}, "© 2026 Centre Évangélique Pentecôtiste Berée · Kinshasa, RDC": {"en": "© 2026 Berea Pentecostal Evangelical Center · Kinshasa, DRC", "pt": "© 2026 Centro Evangélico Pentecostal Bereia · Kinshasa, RDC", "ln": "© 2026 Centre Évangélique Pentecôtiste Berée · Kinshasa, RDC", "sw": "© 2026 Kituo cha Kiinjili cha Kipentekoste cha Berea · Kinshasa, DRC", "lu": "© 2026 Tshibutu tshia Evanjeliyo tshia Pantekoti tshia Bérée · Kinshasa, RDC", "kg": "© 2026 Kimvuka kia Evanjelu kia Pantekoti kia Bérée · Kinshasa, RDC"}, "Bienvenue dans la famille": {"en": "Welcome to the Family", "pt": "Bem-vindo à Família", "ln": "Boyei bolamu na libota", "sw": "Karibu Katika Familia", "lu": "Buakuidi mu dîku", "kg": "Vwakana mu dibuta"}, "Votre place vous attend à Berée.": {"en": "Your Place Awaits You at Berea.", "pt": "Seu Lugar Está à Sua Espera em Bereia.", "ln": "Esika na yo ezali kozela yo na Berée.", "sw": "Nafasi Yako Inakusubiri Berea.", "lu": "Muaba webe udi ukutekemena ku Bérée.", "kg": "Fulu kiaku kikutekemena kuna Berée."}, "Ne venez pas seulement assister à un culte, venez rencontrer une famille.": {"en": "Don't just come to attend a service, come to meet a family.", "pt": "Não venha apenas assistir a um culto, venha conhecer uma família.", "ln": "Yaka kaka te mpo na kotala losambo, yaka mpo na kokutana na libota.", "sw": "Usije tu kuhudhuria ibada, njoo kukutana na familia.", "lu": "Kuluaki anu bua kutangila mulombela to, luaku bua kusangana ne dîku.", "kg": "Kuiza kaka mu tala lusambulu ko, yiza kutana ye dibuta."}, "Voir les horaires": {"en": "See Service Times", "pt": "Ver os Horários", "ln": "Tala bangonga", "sw": "Ona Nyakati", "lu": "Tangila bidiba", "kg": "Tala ntangu"}, "Nous contacter": {"en": "Contact Us", "pt": "Contate-nos", "ln": "Bimela biso", "sw": "Wasiliana Nasi", "lu": "Wakule netu", "kg": "Solula yeto"}, "Plus qu'une église, une famille": {"en": "More Than a Church, a Family", "pt": "Mais que uma Igreja, uma Família", "ln": "Koleka lingomba, libota", "sw": "Zaidi ya Kanisa, ni Familia", "lu": "Kupita dibundu, dîku", "kg": "Kuluta dibundu, dibuta"}, "À Berée, nous croyons que chaque personne a une place unique dans la famille de Dieu.": {"en": "At Berea, we believe every person has a unique place in the family of God.", "pt": "Em Bereia, acreditamos que cada pessoa tem um lugar único na família de Deus.", "ln": "Na Berée, tondimaka ete moto na moto azali na esika na ye ya sika na libota ya Nzambe.", "sw": "Berea, tunaamini kila mtu ana nafasi ya kipekee katika familia ya Mungu.", "lu": "Ku Bérée, tudi tuitabuja ne muntu yonso udi ne muaba wende umue mu dîku dia Nzambi.", "kg": "Kuna Berée, tuena kwikila vo konso muntu wena fulu kiandi mu dibuta dia Nzambi."}, "Nous vous accompagnons dans votre parcours d’intégration.": {"en": "We support you in your journey of integration.", "pt": "Nós o acompanhamos em sua jornada de integração.", "ln": "Tozali kotambola elongo na yo na nzela na yo ya kokota na lisanga.", "sw": "Tunakusindikiza katika safari yako ya kujumuika.", "lu": "Tudi tukulondesha mu njila webe wa kudisangisha.", "kg": "Tukusadisa mu nzila aku ya kukutakana."}, "Communauté": {"en": "Community", "pt": "Comunidade", "ln": "Lisanga", "sw": "Jumuiya", "lu": "Tshisumbu", "kg": "Kimvuka"}, "Rejoignez des groupes de maison et des activités qui créent des relations authentiques et durables dans la foi.": {"en": "Join home groups and activities that create authentic and lasting relationships in the faith.", "pt": "Junte-se a grupos de casa e atividades que criam relações autênticas e duradouras na fé.", "ln": "Sangana na bituluku ya bandako mpe misala oyo esalaka boyokani ya solo mpe ya libela na kondima.", "sw": "Jiunge na vikundi vya nyumbani na shughuli zinazojenga uhusiano wa kweli na wa kudumu katika imani.", "lu": "Wisangana ne bisumbu bia nzubu ne bienzedi bidi bifuka malanda malelela ne a tshikondi tshilelela mu ditabuja.", "kg": "Kutakana ye zimvuka za nzo ye mavanga mamvanganga zinganu za kieleka ye za mvimba mu minu."}, "Accompagnement": {"en": "Guidance", "pt": "Acompanhamento", "ln": "Lisungi", "sw": "Msindikizo", "lu": "Diambuluisha", "kg": "Lusadusu"}, "Un frère ou une sœur dans la foi vous guide personnellement dans vos premiers pas au CEP Berée.": {"en": "A brother or sister in the faith personally guides you in your first steps at CEP Berea.", "pt": "Um irmão ou irmã na fé o guiará pessoalmente em seus primeiros passos no CEP Bereia.", "ln": "Ndeko mobali to ndeko mwasi na kondima akokamba yo moko na matambe na yo ya liboso na CEP Bérée.", "sw": "Ndugu au dada katika imani atakuongoza binafsi katika hatua zako za kwanza CEP Berea.", "lu": "Muanetu mulume anyi mukaji mu ditabuja neakulombole nkayebe mu bikondi biebe bia kumpala ku CEP Bérée.", "kg": "Mpangi yakala voti nkento mu minu wela kutwadisa mu malu maku matheti kuna CEP Bérée."}, "Croissance": {"en": "Growth", "pt": "Crescimento", "ln": "Bokoli", "sw": "Ukuaji", "lu": "Dikola", "kg": "Yela"}, "Formations et enseignements bibliques pour développer votre potentiel spirituel et approfondir votre foi.": {"en": "Biblical training and teachings to develop your spiritual potential and deepen your faith.", "pt": "Formações e ensinamentos bíblicos para desenvolver seu potencial espiritual e aprofundar sua fé.", "ln": "Mateya mpe formasyo ya Biblia mpo na kokolisa makoki na yo ya molimo mpe kokolisa kondima na yo.", "sw": "Mafunzo na mafundisho ya kibiblia kuendeleza uwezo wako wa kiroho na kukuza imani yako.", "lu": "Malongesha ne bilongeshu bia Bible bua kukolesha bukole buebe bua mu nyuma ne kukolesha ditabuja diebe.", "kg": "Malongi ye longoka mu Nkanda Nzambi mu yisa ngolo aku ya mpeve ye kolesa minu kiaku."}, "Service": {"en": "Service", "pt": "Serviço", "ln": "Mosala", "sw": "Huduma", "lu": "Mudimu", "kg": "Kisalu"}, "Trouvez votre place pour servir selon vos talents et passions au sein de nos différents départements.": {"en": "Find your place to serve according to your talents and passions within our various departments.", "pt": "Encontre seu lugar para servir de acordo com seus talentos e paixões em nossos diversos departamentos.", "ln": "Luka esika na yo mpo na kosalela engebene na makoki mpe bolingo na yo kati na ba département na biso ndenge na ndenge.", "sw": "Tafuta nafasi yako ya kutumika kulingana na vipaji na shauku zako ndani ya idara zetu mbalimbali.", "lu": "Wana muaba webe bua kuenzela bilondeshele ne dijinga diebe mu ntu wa bipande bietu bishilangane.", "kg": "Tomba fulu kiaku mu sadila mu diambu dia mayela ye luzolo luaku muna zimpande zeto zi mpila mu mpila."}, "Comment ça se passe ?": {"en": "How Does It Work?", "pt": "Como Funciona?", "ln": "Ndenge nini esalemaka ?", "sw": "Inafanyaje Kazi?", "lu": "Malu enzeka biyi ?", "kg": "Mambu mena bilenda?"}, "Arrivée & Parking": {"en": "Arrival & Parking", "pt": "Chegada e Estacionamento", "ln": "Koya & Parikin", "sw": "Kuwasili na Maegesho", "lu": "Dilua & Parking", "kg": "Lunungu ye Vandu kia Nkangu"}, "Arrivez quelques minutes avant le culte. Un parking est disponible sur place. Notre équipe de sécurité vous orientera dès votre arrivée pour vous faciliter l'accès.": {"en": "Arrive a few minutes before the service. Parking is available on site. Our security team will guide you upon arrival to make access easier.", "pt": "Chegue alguns minutos antes do culto. Há estacionamento disponível no local. Nossa equipe de segurança o orientará assim que chegar para facilitar seu acesso.", "ln": "Koya mwa miniti liboso ya losambo. Parikin ezali wana. Ekipe na biso ya sekurite ekokamba yo tango okokoma mpo na kopesa yo nzela na pete.", "sw": "Wasili dakika chache kabla ya ibada. Maegesho yapo mahali. Timu yetu ya usalama itakuongoza mara utakapowasili ili kurahisisha ufikiaji.", "lu": "Lua kanya kabidi kumpala kua mulombela. Parking wudi muaba au. Tshisumbu tshietu tshia lulama netshikulombole panyi wafika bua kukulejela njila.", "kg": "Iza fioti ntangu kumpala kua lusambulu. Vandu kia nkangu kena vava. Kimvuka kieto kia lulendo kiela kutwadisa panu wela lunga mu kukusadisa nzila."}, "Accueil VIP": {"en": "VIP Welcome", "pt": "Recepção VIP", "ln": "Boyambi VIP", "sw": "Mapokezi ya VIP", "lu": "Diakidila dia VIP", "kg": "Yakusu ya VIP"}, "En tant que nouveau visiteur, vous bénéficiez d'un accueil personnalisé. Notre équipe de protocole vous accompagne, répond à vos questions et vous présente la famille CEP Berée.": {"en": "As a new visitor, you receive a personalized welcome. Our protocol team accompanies you, answers your questions, and introduces you to the CEP Berea family.", "pt": "Como novo visitante, você recebe uma recepção personalizada. Nossa equipe de protocolo o acompanha, responde às suas perguntas e o apresenta à família CEP Bereia.", "ln": "Lokola mopaya ya sika, ozwaka boyambi ya ndenge na yo moko. Ekipe na biso ya protocole elandaka yo, eyanolaka na mituna na yo mpe elakisi yo libota ya CEP Bérée.", "sw": "Kama mgeni mpya, unapata mapokezi ya kipekee. Timu yetu ya itifaki inakusindikiza, kujibu maswali yako na kukuletea familia ya CEP Berea.", "lu": "Bu udi muenyi mupya, udi upeta diakidila dia nkayebe. Tshisumbu tshietu tshia protocole netshikulondeshe, atshandamune nkonko yebe ne kukuleja dîku dia CEP Bérée.", "kg": "Bu wena nzenza yampa, wena tambula yakusu ya nkaka aku. Kimvuka kieto kia protokoli kiela kusadisa, vutula nsangu ziaku ye kukuzabikisa dibuta dia CEP Bérée."}, "L'Expérience": {"en": "The Experience", "pt": "A Experiência", "ln": "Momeseno", "sw": "Uzoefu", "lu": "Diyuka", "kg": "Mona"}, "Vivez un culte chaleureux avec louange, prière et un message inspirant tiré de la Parole de Dieu. Une expérience authentique qui touche le cœur et transforme les vies.": {"en": "Experience a warm service with praise, prayer, and an inspiring message from the Word of God. An authentic experience that touches the heart and transforms lives.", "pt": "Viva um culto caloroso com louvor, oração e uma mensagem inspiradora tirada da Palavra de Deus. Uma experiência autêntica que toca o coração e transforma vidas.", "ln": "Bika losambo ya bolingo elongo na lisanzoli, losambo mpe nsango ya kolendisa euti na Liloba ya Nzambe. Momeseno ya solo oyo esimbaka motema mpe ebongolaka bomoi.", "sw": "Ishi ibada yenye ukarimu na sifa, maombi, na ujumbe wenye kutia moyo kutoka Neno la Mungu. Uzoefu wa kweli unaogusa moyo na kubadilisha maisha.", "lu": "Enza mulombela wa dianga ne disanka, mulombela ne mukenji wa kukolesha muanda kufuma mu Dîyi dia Nzambi. Diyuka dilelela didi diakuata mutshima ne kuakulula mioyo.", "kg": "Zinga lusambulu lua luzolo ye nzitusu, sambu ye nsamu wa kufiokosa muna Diambu dia Nzambi. Mona kia kieleka kimvimba ntima ye sobisa zinga."}, "WhatsApp": {"en": "WhatsApp", "pt": "WhatsApp", "ln": "WhatsApp", "sw": "WhatsApp", "lu": "WhatsApp", "kg": "WhatsApp"}, "Écrivez-nous": {"en": "Write to Us", "pt": "Escreva-nos", "ln": "Komela biso", "sw": "Tuandikie", "lu": "Tufundila", "kg": "Tusonikina"}, "directement": {"en": "directly", "pt": "diretamente", "ln": "na mbala moko", "sw": "moja kwa moja", "lu": "anu pashishi", "kg": "ngolo kaka"}, "Nous sommes là pour vous": {"en": "We Are Here for You", "pt": "Estamos Aqui por Você", "ln": "Tozali awa mpo na yo", "sw": "Tupo Hapa Kwa Ajili Yako", "lu": "Tudi kunku bua yebe", "kg": "Tuena vava mu diambu diaku"}, "Un accompagnement": {"en": "Support", "pt": "Um Acompanhamento", "ln": "Lisungi", "sw": "Msindikizo", "lu": "Diambuluisha", "kg": "Lusadusu"}, "dans la bienveillance": {"en": "with kindness", "pt": "com bondade", "ln": "na bolingo", "sw": "kwa upendo", "lu": "ne dianga", "kg": "mu luzolo"}, "Au CEP Berée, nous croyons que chaque personne mérite d'être écoutée et accompagnée. Nos pasteurs sont disponibles pour vous guider avec discrétion et amour.": {"en": "At CEP Berea, we believe every person deserves to be heard and supported. Our pastors are available to guide you with discretion and love.", "pt": "No CEP Bereia, acreditamos que cada pessoa merece ser ouvida e acompanhada. Nossos pastores estão disponíveis para guiá-lo com discrição e amor.", "ln": "Na CEP Bérée, tondimaka ete moto na moto abongi koyokama mpe kolandama. Bakambi na biso bazali pene mpo na kokamba yo na bopekisi mpe na bolingo.", "sw": "CEP Berea, tunaamini kila mtu anastahili kusikilizwa na kusindikizwa. Wachungaji wetu wapo tayari kukuongoza kwa siri na upendo.", "lu": "Ku CEP Bérée, tudi tuitabuja ne muntu yonso mmuakanyi bua kuteleja ne kulondeshibua. Bafumu betu badi anu pabuipi bua kukulombola ne dinanga ne dianga.", "kg": "Kuna CEP Bérée, tuena kwikila vo konso muntu fwana mu wa ye sadusu. Basambi beto bena mu kutwadisa aku ye kinsueki ye luzolo."}, "Confidentialité Totale": {"en": "Total Confidentiality", "pt": "Confidencialidade Total", "ln": "Kobombama ya mobimba", "sw": "Usiri Kamili", "lu": "Disokoka dionso", "kg": "Kinsueki kimvimba"}, "Le CEP Berée garantit un cadre de discrétion absolue. Vos échanges avec l'équipe pastorale sont protégés et restent strictement confidentiels.": {"en": "CEP Berea guarantees an absolute framework of discretion. Your exchanges with the pastoral team are protected and remain strictly confidential.", "pt": "O CEP Bereia garante um quadro de discrição absoluta. Suas trocas com a equipe pastoral são protegidas e permanecem estritamente confidenciais.", "ln": "CEP Bérée endimisaka ete makambo ekobombama malamu. Masolo na yo na ekipe ya bakambi ekobatelama mpe ekotikala ya sekele.", "sw": "CEP Berea inahakikisha mfumo kamili wa usiri. Mawasiliano yako na timu ya kichungaji yanalindwa na kubaki ya siri kabisa.", "lu": "CEP Bérée udi ujadika muaba wa disokoka dionso. Miakulu yebe ne tshisumbu tshia bafumu idi ilamibua ne kushala mu tshinsuki tshionso.", "kg": "CEP Bérée ukukumina kinsueki kimvimba. Miyowulu miaku ye kimvuka kia basambi milama ye zinga kinsueki kimvimba."}, "Conseil Biblique": {"en": "Biblical Counsel", "pt": "Aconselhamento Bíblico", "ln": "Toli ya Biblia", "sw": "Ushauri wa Kibiblia", "lu": "Mibelu ya Bible", "kg": "Ndongi mu Nkand'a Nzambi"}, "Face aux doutes ou aux choix difficiles, nos pasteurs vous aident à trouver une perspective claire et des réponses fondées sur la Parole de Dieu.": {"en": "Facing doubts or difficult choices, our pastors help you find a clear perspective and answers grounded in the Word of God.", "pt": "Diante de dúvidas ou escolhas difíceis, nossos pastores o ajudam a encontrar uma perspectiva clara e respostas fundamentadas na Palavra de Deus.", "ln": "Liboso ya ntembe to biponami ya mpasi, bakambi na biso basungaka yo mpo na koluka bososoli ya polele mpe biyano oyo etongami na Liloba ya Nzambe.", "sw": "Unapokabiliwa na mashaka au maamuzi magumu, wachungaji wetu wanakusaidia kupata mtazamo wazi na majibu yaliyojikita katika Neno la Mungu.", "lu": "Kumpala kua lujingu anyi masangu makole, bafumu betu badi bakuambuluisha bua kuwana diakalenga dilengele ne mandamuna madi majadike mu Dîyi dia Nzambi.", "kg": "Ku ntuala zi phukuta voti nsobolo za mpasi, basambi beto bakusadisanga mu bakula mona diaka ye mvutu zijikama mu Diambu dia Nzambi."}, "Soutien par la Prière": {"en": "Support through Prayer", "pt": "Apoio pela Oração", "ln": "Lisungi na losambo", "sw": "Msaada kwa Maombi", "lu": "Diambuluisha kudi mulombela", "kg": "Lusadusu mu Sambu"}, "Personne n'est censé marcher seul. Nous nous tenons à vos côtés pour intercéder et croire avec vous pour votre restauration et votre paix.": {"en": "No one is meant to walk alone. We stand by your side to intercede and believe with you for your restoration and peace.", "pt": "Ninguém deve caminhar sozinho. Estamos ao seu lado para interceder e crer com você por sua restauração e sua paz.", "ln": "Moto moko te asengeli kotambola ye moko. Tozali pembeni na yo mpo na kobondela mpe kondima elongo na yo mpo na kozongisama na yo mpe kimia na yo.", "sw": "Hakuna anayepaswa kutembea peke yake. Tunasimama pembeni yako kuombea na kuamini pamoja nawe kwa ajili ya kurejeshwa kwako na amani yako.", "lu": "Kakuena muntu wa kwenda enka to. Tudi patupamue nebe bua kulombela ne kwitabuja nebe bua dikuatshika diebe ne ditalala diebe.", "kg": "Ka kuena muntu wa kuenda niandi veka ko. Tuena vava vovo aku mu lomba ye kwikila yaku mu diambu dia vutukusu ye ngemba aku."}, "« Portez les fardeaux les uns des autres, et vous accomplirez ainsi la loi de Christ. »": {"en": "\"Carry each other's burdens, and in this way you will fulfill the law of Christ.\"", "pt": "\"Levai as cargas uns dos outros, e assim cumprireis a lei de Cristo.\"", "ln": "« Bomemana mikumba ya bino na bino, mpe bokokokisa mobeko ya Klisto. »", "sw": "\"Bebeni mizigo ya kila mmoja, na hivyo mtaitimiza sheria ya Kristo.\"", "lu": "« Nyemenganayi bujitu buenu, nenu nenulondeshe mikenji ya Kristo. »", "kg": "« Nataninanu mfuna zieno, ye nulungisa nsiku za Kristu. »"}, "— Galates 6:2": {"en": "— Galatians 6:2", "pt": "— Gálatas 6:2", "ln": "— Bagalatia 6:2", "sw": "— Wagalatia 6:2", "lu": "— Galatia 6:2", "kg": "— Ngalatia 6:2"}, "Prenez contact": {"en": "Get in Touch", "pt": "Entre em Contato", "ln": "Kokutana", "sw": "Wasiliana", "lu": "Wakule", "kg": "Solula"}, "Envoyer un message": {"en": "Send a Message", "pt": "Enviar uma Mensagem", "ln": "Kotinda nsango", "sw": "Tuma Ujumbe", "lu": "Tuma lumu", "kg": "Fidisa nsamu"}, "au pasteur": {"en": "to the pastor", "pt": "ao pastor", "ln": "epai ya mokambi", "sw": "kwa mchungaji", "lu": "kudi mfumu", "kg": "kua nsambi"}, "Remplissez ce formulaire et votre message sera transmis directement au pasteur via WhatsApp. Nous vous répondons dans les meilleurs délais.": {"en": "Fill out this form and your message will be sent directly to the pastor via WhatsApp. We will respond as soon as possible.", "pt": "Preencha este formulário e sua mensagem será enviada diretamente ao pastor via WhatsApp. Responderemos o mais breve possível.", "ln": "Tondisa fomilere oyo mpe nsango na yo ekokende na mbala moko epai ya mokambi na nzela ya WhatsApp. Tokoyanola yo na ntango moke.", "sw": "Jaza fomu hii na ujumbe wako utatumwa moja kwa moja kwa mchungaji kupitia WhatsApp. Tutakujibu haraka iwezekanavyo.", "lu": "Wuja fomo eu ne lumu luebe nelutumibue anu pashishi kudi mfumu ku WhatsApp. Netukuandamuna lukasa.", "kg": "Fuana fomu yayi ye nsamu ya kwenda ngolo kua nsambi mu WhatsApp. Tuela kuvutula nswalu."}, "Nom complet": {"en": "Full Name", "pt": "Nome Completo", "ln": "Kombo mobimba", "sw": "Jina Kamili", "lu": "Dîna dijima", "kg": "Zina kimvimba"}, "(optionnel)": {"en": "(optional)", "pt": "(opcional)", "ln": "(esengeli te)", "sw": "(hiari)", "lu": "(kabiyi bua bulelela)", "kg": "(ka mfunu ko)"}, "Sujet": {"en": "Subject", "pt": "Assunto", "ln": "Likambo", "sw": "Somo", "lu": "Bualu", "kg": "Diambu"}, "Votre message": {"en": "Your Message", "pt": "Sua Mensagem", "ln": "Nsango na yo", "sw": "Ujumbe Wako", "lu": "Lumu luebe", "kg": "Nsamu aku"}, "← Retour à l'accueil": {"en": "← Back to Home", "pt": "← Voltar ao Início", "ln": "← Kozonga na ebandeli", "sw": "← Rudi Nyumbani", "lu": "← Vutuka ku Kutuadijila", "kg": "← Vutuka ku Nzo"}, "Le plus beau choix de votre vie": {"en": "The Most Beautiful Choice of Your Life", "pt": "A Escolha Mais Bonita da Sua Vida", "ln": "Boponami ya kitoko koleka na bomoi na yo", "sw": "Uamuzi Mzuri Zaidi wa Maisha Yako", "lu": "Musangu mubi wa muoyo webe", "kg": "Nsobolo yimboti ya luzingu luaku"}, "Donner ma vie": {"en": "Give My Life", "pt": "Dar Minha Vida", "ln": "Kopesa bomoi na ngai", "sw": "Kutoa Maisha Yangu", "lu": "Kupesha muoyo wanyi", "kg": "Vana luzingu luame"}, "à Jésus": {"en": "to Jesus", "pt": "a Jesus", "ln": "epai ya Yesu", "sw": "kwa Yesu", "lu": "kudi Yezu", "kg": "kua Yezu"}, "Ce n'est pas une religion — c'est une relation. Une décision qui change tout, pour toujours.": {"en": "It's not a religion — it's a relationship. A decision that changes everything, forever.", "pt": "Não é uma religião — é um relacionamento. Uma decisão que muda tudo, para sempre.", "ln": "Ezali lingomba te — ezali boyokani. Ekateli oyo ebongolaka nyonso, libela na libela.", "sw": "Sio dini — ni uhusiano. Uamuzi unaobadilisha kila kitu, milele.", "lu": "Kabiena dinanga to — mmusomba. Dipangadika didi diakuluula bionso, tshiendelele.", "kg": "Ka i dinanga ko — i kithuadi. Nsobolo yisobisa mamu moso, mvimba."}, "Faire ce pas maintenant": {"en": "Take This Step Now", "pt": "Dar Este Passo Agora", "ln": "Sala litambe oyo sikoyo", "sw": "Chukua Hatua Hii Sasa", "lu": "Enza tshishishi etshi mpindieu", "kg": "Sala mambu mama bwabu"}, "Que se passe-t-il": {"en": "What Happens", "pt": "O Que Acontece", "ln": "Nini esalemaka", "sw": "Nini Kinachotokea", "lu": "Ntu udi wenza", "kg": "Mambu mena mavangama"}, "quand je dis": {"en": "when I say", "pt": "quando eu digo", "ln": "tango nalobi", "sw": "ninaposema", "lu": "padi ngamba", "kg": "mu thangu ndituba"}, "Oui ?": {"en": "Yes?", "pt": "Sim?", "ln": "Ee ?", "sw": "Ndiyo?", "lu": "Eyowa ?", "kg": "Iyi?"}, "Le Pardon": {"en": "Forgiveness", "pt": "O Perdão", "ln": "Bolimbisi", "sw": "Msamaha", "lu": "Diakidibua", "kg": "Nlemvo"}, "Donner sa vie à Jésus, c'est recevoir Son pardon total. Dieu ne regarde plus vos erreurs passées ; Il vous voit à travers Son amour et vous offre une page blanche.": {"en": "Giving your life to Jesus means receiving His total forgiveness. God no longer looks at your past mistakes; He sees you through His love and offers you a clean slate.", "pt": "Dar a vida a Jesus é receber Seu perdão total. Deus não olha mais para os seus erros passados; Ele vê você através do Seu amor e lhe oferece uma página em branco.", "ln": "Kopesa bomoi na yo epai ya Yesu, wana wana ozwi bolimbisi na Ye ya mobimba. Nzambe atalaka lisusu te mabunga na yo ya kala ; Amonaka yo na nzela ya bolingo na Ye mpe apesaka yo lokasa ya pembe.", "sw": "Kutoa maisha yako kwa Yesu ni kupokea msamaha wake kamili. Mungu haangalii tena makosa yako ya zamani; Anakuona kupitia upendo wake na kukupa fursa mpya.", "lu": "Kupesha muoyo webe kudi Yezu mmumona diakidibua diende dijima. Nzambi kena utangila lusama luebe lua kale kabidi; Wudi ukumona ku diambu dia dinanga diende ne wukupesha lupepele lupiabipia.", "kg": "Vana luzingu luaku kua Yezu i tambula nlemvo andi mvimba. Nzambi ka bu talanga diaka nsobolo aku za kala ko; Wukumonanga mu luzolo luandi ye kukuvana nkanda mvelo."}, "La Relation": {"en": "The Relationship", "pt": "O Relacionamento", "ln": "Boyokani", "sw": "Uhusiano", "lu": "Malanda", "kg": "Kithuadi"}, "Ce n'est pas une religion, c'est une amitié. En acceptant Christ, vous devenez enfant de Dieu. Son Esprit vient habiter en vous pour vous guider et vous conseiller chaque jour.": {"en": "It is not a religion, it is a friendship. By accepting Christ, you become a child of God. His Spirit comes to live in you to guide and counsel you every day.", "pt": "Não é uma religião, é uma amizade. Ao aceitar Cristo, você se torna filho de Deus. Seu Espírito vem habitar em você para guiá-lo e aconselhá-lo todos os dias.", "ln": "Ezali lingomba te, ezali boninga. Na kondima Klisto, okomi mwana ya Nzambe. Molimo na Ye ayaka kofanda na kati na yo mpo na kokamba yo mpe kopesa yo toli mokolo na mokolo.", "sw": "Sio dini, ni urafiki. Kwa kumkubali Kristo, unakuwa mtoto wa Mungu. Roho wake anakuja kuishi ndani yako kukuongoza na kukushauri kila siku.", "lu": "Kabiena dinanga to, mmubuobo. Bua kuitaba Kristo, udi ulua muana wa Nzambi. Nyuma wende udi ulua kusombela mudimu bua kukulombola ne kukupesha mibelu dituku ne dituku.", "kg": "Ka i dinanga ko, i kinkundi. Mu tambula Kristu, wukituka muana Nzambi. Mpeve andi wieza vwanda mu ngeye mu kutwadisa ye kuvana ndongi konso lumbu."}, "L'Avenir": {"en": "The Future", "pt": "O Futuro", "ln": "Mikolo ekoya", "sw": "Wakati Ujao", "lu": "Matuku akuiza", "kg": "Lusukulu"}, "C'est le début d'une transformation qui impactera votre caractère, votre famille et votre futur. Vous recevez une paix et une espérance que le monde ne peut donner.": {"en": "It is the beginning of a transformation that will impact your character, your family, and your future. You receive a peace and hope that the world cannot give.", "pt": "É o início de uma transformação que impactará seu caráter, sua família e seu futuro. Você recebe uma paz e uma esperança que o mundo não pode dar.", "ln": "Ezali ebandeli ya mbongwana oyo ekosala na bizaleli na yo, libota na yo mpe mikolo ekoya na yo. Ozwaka kimia mpe elikya oyo mokili ekoki kopesa te.", "sw": "Ni mwanzo wa mabadiliko yatakayoathiri tabia yako, familia yako na wakati wako ujao. Unapokea amani na tumaini ambalo dunia haiwezi kutoa.", "lu": "Mmubadi wa kusobisha kudi kukuma mu bikadilu biebe, dîku diebe ne matuku aebe akuiza. Udi utambula ditalala ne ditekemena didi bulongo kabuena mua kupesha.", "kg": "I nyantikulu a nsobolo yela vanga nsualu aku, dibuta diaku ye lusukulu luaku. Utambudi ngemba ye ditekemena kikadi nza lenda vana."}, "Faites ce pas": {"en": "Take This Step", "pt": "Dê Este Passo", "ln": "Sala litambe oyo", "sw": "Chukua Hatua Hii", "lu": "Enza tshishishi etshi", "kg": "Sala mambu mama"}, "Prière de salut": {"en": "Prayer of Salvation", "pt": "Oração de Salvação", "ln": "Losambo ya lobiko", "sw": "Maombi ya Wokovu", "lu": "Mulombela wa lupandu", "kg": "Sambu kia Phulusu"}, "Si vous êtes prêt, priez cette prière du fond de votre cœur. Dieu vous entend.": {"en": "If you are ready, pray this prayer from the depths of your heart. God hears you.", "pt": "Se você está pronto, ore esta oração do fundo do seu coração. Deus o ouve.", "ln": "Soki ozali pene, bondela losambo oyo na motema na yo mobimba. Nzambe ayokaka yo.", "sw": "Ukiwa tayari, omba maombi haya kutoka moyoni mwako. Mungu anakusikia.", "lu": "Bikala udibumbe, lombela mulombela eu ne mutshima webe mujima. Nzambi udi ukuteleja.", "kg": "Kana wena kubongama, samba sambu kiaki mu ntima aku mvimba. Nzambi ukuwilu."}, "« Seigneur Jésus, je reconnais que je suis pécheur et que j'ai besoin de toi. Je crois que tu es mort pour mes péchés et que tu es ressuscité. Je te demande pardon pour tout ce que j'ai fait de mal. Entre dans ma vie, sois mon Seigneur et mon Sauveur. À partir d'aujourd'hui, je veux te suivre. Amen. »": {"en": "\"Lord Jesus, I acknowledge that I am a sinner and that I need you. I believe that you died for my sins and that you rose again. I ask your forgiveness for everything I have done wrong. Come into my life, be my Lord and Savior. From today, I want to follow you. Amen.\"", "pt": "\"Senhor Jesus, reconheço que sou pecador e que preciso de ti. Creio que morreste pelos meus pecados e ressuscitaste. Peço-te perdão por tudo o que fiz de errado. Entra na minha vida, sê meu Senhor e Salvador. A partir de hoje, quero seguir-te. Amém.\"", "ln": "« Nkolo Yesu, nandimi ete nazali na masumu mpe nazali na mposa na yo. Nandimi ete okufaki mpo na masumu na ngai mpe osekwaki. Nasengi yo bolimbisi mpo na makambo nyonso ya mabe nasalaki. Kota na bomoi na ngai, zala Nkolo mpe Mobikisi na ngai. Kobanda lelo, nalingi kolanda yo. Amen. »", "sw": "\"Bwana Yesu, nakiri kwamba mimi ni mwenye dhambi na ninakuhitaji. Naamini ulikufa kwa ajili ya dhambi zangu na ulifufuka. Nakuomba unisamehe kwa kila jambo baya nililofanya. Ingia katika maisha yangu, uwe Bwana na Mwokozi wangu. Kuanzia leo, nataka kukufuata. Amina.\"", "lu": "« Mfumu Yezu, ndi umanya ne ndi muena mibi ne ndi ne dijinga diebe. Ndi witabuja ne wakafua bua mibi yanyi ne wakabika kabidi. Ndi kulomba diakidibua bua bionso bibi bindi muenza. Bua mu muoyo wanyi, ikala Mfumu ne Mupandishi wanyi. Kutuadijila lelu, ndi musue kulonda. Amen. »", "kg": "« Mfumu Yezu, ndi zabidi vo ndi nkua masumu ye ndi ye mfunu aku. Ndi kwikila vo wufwidi mu masumu mama ye wufulukidi. Ndi kulomba nlemvo mu mamu moso mambi ndivanga. Kota mu luzingu luame, wukala Mfumu ye Mvulusi ame. Tona lelu, ndizolele kulanda ngeye. Amen. »"}, "« Si quelqu'un est en Christ, il est une nouvelle créature. Les choses anciennes sont passées ; voici, toutes choses sont devenues nouvelles. »": {"en": "\"If anyone is in Christ, he is a new creation. The old has passed away; behold, all things have become new.\"", "pt": "\"Se alguém está em Cristo, é nova criatura. As coisas antigas já passaram; eis que tudo se fez novo.\"", "ln": "« Soki moto azali kati na Klisto, azali ekelamu ya sika. Makambo ya kala eleki ; tala, makambo nyonso ekomi ya sika. »", "sw": "\"Kama mtu yeyote yumo ndani ya Kristo, yeye ni kiumbe kipya. Mambo ya kale yamepita; tazama, mambo yote yamekuwa mapya.\"", "lu": "« Bikala muntu udi mu Kristo, udi tshifukibua tshipia. Malu makulukulu mapite ; tangila, malu onso alua mapia. »", "kg": "« Kana muntu wena mu Kristu, i mvangu yampa. Mamu ma khulu mavioka; tala, mamu moso masobana mampa. »"}, "— 2 Corinthiens 5:17": {"en": "— 2 Corinthians 5:17", "pt": "— 2 Coríntios 5:17", "ln": "— 2 Bakorinti 5:17", "sw": "— 2 Wakorintho 5:17", "lu": "— 2 Kolinto 5:17", "kg": "— 2 Kolinto 5:17"}, "Foire aux questions": {"en": "Frequently Asked Questions", "pt": "Perguntas Frequentes", "ln": "Mituna oyo etunamaka mingi", "sw": "Maswali Yanayoulizwa Mara kwa Mara", "lu": "Nkonko idi ipetibua misangu ne misangu", "kg": "Nsangu Zinlombolo Zingi"}, "Qu'est-ce que cela signifie concrètement de \"donner sa vie\" ?": {"en": "What does it practically mean to \"give your life\"?", "pt": "O que significa na prática \"dar a vida\"?", "ln": "Yango elingi koloba nini na komona polele \"kopesa bomoi\" ?", "sw": "Ina maana gani hasa \"kutoa maisha yako\"?", "lu": "Ntu diambu edi diakuenzeke bua \"kupesha muoyo\" ?", "kg": "Nki i nsundu ya \"vana luzingu\" mu bukiedika?"}, "Donner sa vie à Jésus, ce n'est pas rejoindre une religion, mais débuter une relation personnelle avec votre Créateur. C'est décider de Lui faire confiance, de recevoir Son pardon pour vos erreurs passées et de Le laisser diriger votre vie pour un futur rempli de paix et de but.": {"en": "Giving your life to Jesus is not joining a religion, but starting a personal relationship with your Creator. It is deciding to trust Him, to receive His forgiveness for your past mistakes, and to let Him direct your life for a future full of peace and purpose.", "pt": "Dar a vida a Jesus não é aderir a uma religião, mas iniciar um relacionamento pessoal com seu Criador. É decidir confiar Nele, receber Seu perdão pelos seus erros passados e deixá-Lo dirigir sua vida para um futuro cheio de paz e propósito.", "ln": "Kopesa bomoi epai ya Yesu, ezali kokota na lingomba te, kasi kobanda boyokani ya moto na moto na Mozalisi na yo. Ezali kozwa ekateli ya kotiela Ye motema, kozwa bolimbisi na Ye mpo na mabunga na yo ya kala mpe kotika Ye akamba bomoi na yo mpo na mikolo ekoya etonda na kimia mpe na ntina.", "sw": "Kutoa maisha yako kwa Yesu si kujiunga na dini, bali kuanza uhusiano wa kibinafsi na Muumba wako. Ni kuamua kumwamini, kupokea msamaha wake kwa makosa yako ya zamani na kumwacha aongoze maisha yako kwa wakati ujao uliojaa amani na kusudi.", "lu": "Kupesha muoyo kudi Yezu, kabiena kubuela mu dinanga to, kadi mmutuadija malanda a muntu ne Mufuki webe. Mmumona dipangadika dia kumueyakidila, kutambula diakidibua diende bua nsama yebe ya kale ne kumulekela mmulombole muoyo webe bua matuku akuiza matuke a ditalala ne tshipatshila.", "kg": "Vana luzingu kua Yezu, ka i kotila mu dinanga ko, kansi i yantika kithuadi kiaku ye Mvangi aku. I baka nsobolo ya kumfiaulwa, tambula nlemvo andi mu nsobolo aku za khulu ye kumbika kalombola luzingu luaku mu lusukulu lulembo ngemba ye nzaka."}, "Est-ce que mon passé ou mes erreurs peuvent m'empêcher de suivre Dieu ?": {"en": "Can my past or my mistakes prevent me from following God?", "pt": "Meu passado ou meus erros podem me impedir de seguir a Deus?", "ln": "Boni lisolo na ngai ya kala to mabunga na ngai ekoki kopekisa ngai kolanda Nzambe ?", "sw": "Je, historia yangu au makosa yangu vinaweza kunizuia kumfuata Mungu?", "lu": "Muanda wanyi wa kale anyi bilema byanyi bidi mua kungengesha bua kulonda Nzambi anyi ?", "kg": "Mbandu ame voti nsobolo zame zilenda kutsina lundu Nzambi ?"}, "Absolument pas. La grâce de Dieu ne dépend pas de ce que vous avez fait ou n'avez pas fait. Peu importe votre passé, Dieu vous accueille tel que vous êtes. La Bible dit que « là où le péché a abondé, la grâce a surabondé » (Romains 5:20). Votre passé ne définit pas votre avenir avec Dieu.": {"en": "Absolutely not. God's grace does not depend on what you have or have not done. No matter your past, God welcomes you as you are. The Bible says that \"where sin increased, grace increased all the more\" (Romans 5:20). Your past does not define your future with God.", "pt": "Absolutamente não. A graça de Deus não depende do que você fez ou deixou de fazer. Não importa o seu passado, Deus o acolhe como você é. A Bíblia diz que \"onde o pecado abundou, a graça superabundou\" (Romanos 5:20). Seu passado não define seu futuro com Deus.", "ln": "Ata moke te. Ngolu ya Nzambe eyokani na makambo osalaki to osalaki te. Ezala lisolo na yo ezali ndenge nini, Nzambe ayambaka yo ndenge ozali. Biblia elobi ete « esika masumu ekomaki mingi, ngolu eyaki mingi koleka » (Baroma 5:20). Lisolo na yo ya kala ekokataka mikolo na yo ekoya na Nzambe te.", "sw": "Hapana kabisa. Neema ya Mungu haitegemei kile ulichofanya au usichofanya. Haijalishi historia yako, Mungu anakukaribisha jinsi ulivyo. Biblia inasema kwamba \"pale dhambi ilipozidi, neema ilizidi zaidi\" (Warumi 5:20). Historia yako haiamui wakati wako ujao na Mungu.", "lu": "Kutupu nansha kakese. Ngasa wa Nzambi kawuyi ulondela bidi muenze anyi kabiyi muenze. Nansha muanda webe udi biyi, Nzambi udi ukuakidila bu udi. Bible udi wamba ne « muaba mubi wakula, ngasa wakula kupita to » (Loma 5:20). Muanda webe wa kale kawuena upangadika lusukulu luebe ne Nzambi.", "kg": "Nkatu ko. Nlemvo wa Nzambi kawulembo singikidi mu mamu wuvanga voti kuvanga ko. Ka bu didi mbandu aku, Nzambi ukuakisanga bu wena. Nkanda wa Nzambi utuba vo \"kuna disumu diayingana, nlemvo wuyingana kuluta\" (Loma 5:20). Mbandu aku ka yisadilanga lusukulu luaku ye Nzambi ko."}, "J'ai fait la prière de salut aujourd'hui, quelle est la prochaine étape ?": {"en": "I said the prayer of salvation today, what is the next step?", "pt": "Fiz a oração de salvação hoje, qual é o próximo passo?", "ln": "Nasali losambo ya lobiko lelo, litambe oyo elandi ezali nini ?", "sw": "Nimeomba maombi ya wokovu leo, hatua inayofuata ni ipi?", "lu": "Ndi muenze mulombela wa lupandu lelu, tshishishi tshilonda ntshinyi ?", "kg": "Ndisambidi sambu kia phulusu lelu, kima kilanda i nki?"}, "Félicitations ! Voici les premières étapes : commencez à lire la Bible (l'Évangile de Jean est un bon départ), priez chaque jour, rejoignez une église locale comme le CEP Berée, et partagez votre décision avec quelqu'un de confiance. Contactez-nous pour vous accompagner dans ce nouveau départ.": {"en": "Congratulations! Here are the first steps: start reading the Bible (the Gospel of John is a good starting point), pray every day, join a local church like CEP Berea, and share your decision with someone you trust. Contact us to support you in this new beginning.", "pt": "Parabéns! Aqui estão os primeiros passos: comece a ler a Bíblia (o Evangelho de João é um bom começo), ore todos os dias, junte-se a uma igreja local como o CEP Bereia, e compartilhe sua decisão com alguém de confiança. Contate-nos para acompanhá-lo neste novo começo.", "ln": "Longonya ! Tala matambe ya liboso : banda kotanga Biblia (Evanjile ya Yoane ezali ebandeli malamu), bondelaka mokolo na mokolo, kota na lingomba ya mboka lokola CEP Bérée, mpe kabola ekateli na yo na moto oyo otielaka motema. Bimela biso mpo na kolanda yo na ebandeli ya sika oyo.", "sw": "Hongera! Hizi ni hatua za kwanza: anza kusoma Biblia (Injili ya Yohana ni mwanzo mzuri), omba kila siku, jiunge na kanisa la mtaa kama CEP Berea, na shiriki uamuzi wako na mtu unayemwamini. Wasiliana nasi tukusindikize katika mwanzo huu mpya.", "lu": "Diakalenga ! Tala bikondi bia kumpala : tuadija kubala Bible (Evanjeliyo dia Yowano didi ntuadijilu dimpe), lombela dituku ne dituku, wisangana ne dibundu dia muaba anga CEP Bérée, ne kudisangisha dipangadika diebe ne muntu udi wewitabuja. Wakule netu bua kukulondesha mu ntuadijilu eu mupya.", "kg": "Nsakumunu! Tala malu matheti: yantika tanga Nkanda wa Nzambi (Evanjelu kia Yoane i ntuadulu yambote), samba konso lumbu, kutakana ye dibundu kia zunga banga CEP Bérée, ye kabula nsobolo aku ye muntu wukwikilanga. Solula yeto mu kutwadisa mu ntuadulu yampa yayi."}, "Comment puis-je apprendre à prier et à comprendre la Bible ?": {"en": "How can I learn to pray and understand the Bible?", "pt": "Como posso aprender a orar e a entender a Bíblia?", "ln": "Nakoki ndenge nini koyekola kobondela mpe kososola Biblia ?", "sw": "Ninawezaje kujifunza kuomba na kuelewa Biblia?", "lu": "Ndi mua kulonga biyi bua kulombela ne kupetulula Bible ?", "kg": "Ndilenda longuka phila ya samba ye bakula Nkanda wa Nzambi?"}, "La prière c'est simplement parler à Dieu comme à un ami, pas besoin de formules compliquées. Pour la Bible, commencez par l'Évangile de Jean, puis les Psaumes. Au CEP Berée, nous proposons un d'étude biblique le mardi et jeudi de 17h à 19h. Venez nous rejoindre !": {"en": "Prayer is simply talking to God as to a friend, no need for complicated formulas. For the Bible, start with the Gospel of John, then the Psalms. At CEP Berea, we offer Bible study on Tuesdays and Thursdays from 5 PM to 7 PM. Come join us!", "pt": "A oração é simplesmente falar com Deus como a um amigo, sem necessidade de fórmulas complicadas. Para a Bíblia, comece pelo Evangelho de João, depois os Salmos. No CEP Bereia, oferecemos um estudo bíblico às terças e quintas das 17h às 19h. Venha se juntar a nós!", "ln": "Losambo ezali kaka kosolola na Nzambe lokola na moninga, esengeli te na mangomba ya mindule. Mpo na Biblia, banda na Evanjile ya Yoane, na sima Banzembo. Na CEP Bérée, topesaka boyekoli ya Biblia mokolo ya misato mpe minei kobanda na ngonga 17h kino 19h. Yaka osangana na biso !", "sw": "Maombi ni kuzungumza tu na Mungu kama rafiki, hakuna haja ya maneno magumu. Kwa Biblia, anza na Injili ya Yohana, kisha Zaburi. CEP Berea, tunatoa mafunzo ya Biblia Jumanne na Alhamisi saa 11 hadi saa 1 jioni. Njoo ujiunge nasi!", "lu": "Mulombela mmusolola ne Nzambi anu bu ne mulunda, kabiyi mfunu wa mêyi makole. Bua Bible, tuadija ne Evanjeliyo dia Yowano, kunyima Misambu. Ku CEP Bérée, tudi tuenza dilongesha dia Bible mardi ne jeudi kutuadijila 17h too ne 19h. Luaku wisangane netu !", "kg": "Sambu i solula kaka ye Nzambi banga ye nkundi, ka mfunu wa mambu ma phasi ko. Mu Nkanda wa Nzambi, tuadila Evanjelu kia Yoane, kuna Mimvimba. Kuna CEP Bérée, tuena vana longoka mu Nkand'a Nzambi mu nzoono ye nkази tona 17h too na 19h. Yiza kutakana yeto!"}, "Dois-je me faire baptiser après avoir donné ma vie à Jésus ?": {"en": "Should I get baptized after giving my life to Jesus?", "pt": "Devo ser batizado depois de dar minha vida a Jesus?", "ln": "Nasengeli kozwa libatisi sima ya kopesa bomoi na ngai epai ya Yesu ?", "sw": "Je, ninapaswa kubatizwa baada ya kutoa maisha yangu kwa Yesu?", "lu": "Ndi ne bua kubatiza panyima pa kupesha muoyo wanyi kudi Yezu anyi ?", "kg": "Fwene mu botama kunima kua vana luzingu luame kua Yezu?"}, "Le baptême est une étape importante après la conversion. C'est un acte d'obéissance et de témoignage public de votre foi. Jésus lui-même a été baptisé et nous invite à l'être. Contactez-nous pour vous inscrire à notre prochain service de baptême.": {"en": "Baptism is an important step after conversion. It is an act of obedience and a public testimony of your faith. Jesus himself was baptized and invites us to be as well. Contact us to sign up for our next baptism service.", "pt": "O batismo é uma etapa importante após a conversão. É um ato de obediência e testemunho público da sua fé. O próprio Jesus foi batizado e nos convida a sê-lo. Contate-nos para se inscrever em nosso próximo culto de batismo.", "ln": "Libatisi ezali litambe ya ntina sima ya kobongwana. Ezali ekela ya botosi mpe litatoli ya polele ya kondima na yo. Yesu ye moko azwaki libatisi mpe abengisaka biso tosala bongo. Bimela biso mpo na kokomisa nkombo na yo na losambo na biso ya libatisi oyo elandi.", "sw": "Ubatizo ni hatua muhimu baada ya wongofu. Ni tendo la utii na ushuhuda wa hadharani wa imani yako. Yesu mwenyewe alibatizwa na anatualika tufanye hivyo. Wasiliana nasi kujiandikisha kwa ibada yetu ijayo ya ubatizo.", "lu": "Dibatiza didi tshishishi tshinene panyima pa dishintuluka. Mmuenzedi wa buloba ne bumanyi bua tshianza tshia ditabuja diebe. Yezu nkayende wakabatizibua ne udi utubikila bua tuenze bua. Wakule netu bua kudifundisha ku mudimu wetu wa dibatiza udi ulonda.", "kg": "Botama i kima kianene kunima kua nsobolo. I mvangu wa lemvokolo ye kimbangi kia batu boso kia minu kiaku. Yezu niandi veka wubatuka ye ukutubikidi mu vanga bobo. Solula yeto mu difunda mu lusambulu lweto lulanda lua botama."}, "Vous venez de faire ce pas ?": {"en": "Did you just take this step?", "pt": "Você acabou de dar este passo?", "ln": "Owuti kosala litambe oyo ?", "sw": "Je, umechukua hatua hii?", "lu": "Udi mua kuenza tshishishi etshi anyi ?", "kg": "Ngeye wusala mambu mama ubwabu?"}, "Nous voulons prier avec vous et vous accompagner dans vos premiers pas avec Christ.": {"en": "We want to pray with you and accompany you in your first steps with Christ.", "pt": "Queremos orar com você e acompanhá-lo em seus primeiros passos com Cristo.", "ln": "Tolingi kobondela elongo na yo mpe kolanda yo na matambe na yo ya liboso elongo na Klisto.", "sw": "Tunataka kuomba nawe na kukusindikiza katika hatua zako za kwanza na Kristo.", "lu": "Tudi tujinga kulombela nebe ne kukulondesha mu bikondi biebe bia kumpala ne Kristo.", "kg": "Tuzolele samba yaku ye kukusadisa mu malu maku matheti ye Kristu."}, "Contacter le pasteur": {"en": "Contact the Pastor", "pt": "Contatar o Pastor", "ln": "Kobenga mokambi", "sw": "Wasiliana na Mchungaji", "lu": "Wakule ne mfumu", "kg": "Solula ye Nsambi"}, "Une étape essentielle": {"en": "An Essential Step", "pt": "Uma Etapa Essencial", "ln": "Litambe ya ntina mingi", "sw": "Hatua Muhimu", "lu": "Tshishishi tshinene", "kg": "Kima kianene"}, "Me faire": {"en": "Get", "pt": "Ser", "ln": "Kozwa", "sw": "Kubatizwa", "lu": "Kubatiza", "kg": "Botama"}, "baptiser": {"en": "baptized", "pt": "batizado", "ln": "libatisi", "sw": "", "lu": "", "kg": ""}, "Le baptême est un acte d'obéissance et de témoignage public de votre foi en Jésus-Christ. Une déclaration devant Dieu, les anges et les hommes.": {"en": "Baptism is an act of obedience and a public testimony of your faith in Jesus Christ. A declaration before God, the angels, and men.", "pt": "O batismo é um ato de obediência e testemunho público da sua fé em Jesus Cristo. Uma declaração diante de Deus, dos anjos e dos homens.", "ln": "Libatisi ezali ekela ya botosi mpe litatoli ya polele ya kondima na yo na Yesu-Klisto. Elobeli liboso ya Nzambe, baanzelu mpe bato.", "sw": "Ubatizo ni tendo la utii na ushuhuda wa hadharani wa imani yako katika Yesu Kristo. Tamko mbele za Mungu, malaika na wanadamu.", "lu": "Dibatiza didi mvangu wa lemvokolo ne bumanyi bua tshianza tshia ditabuja diebe mu Yezu-Kristo. Muambila kumpala kua Nzambi, banjelo ne bantu.", "kg": "Botama i mvangu wa lemvokolo ye kimbangi kia batu boso kia minu kiaku mu Yezu-Kristu. Ntubulu ku ntuala Nzambi, zimbasi ye batu."}, "M'inscrire maintenant": {"en": "Sign Up Now", "pt": "Inscrever-se Agora", "ln": "Komisa nkombo na ngai sikoyo", "sw": "Jisajili Sasa", "lu": "Difundisha dîna diebe mpindieu", "kg": "Sonika zina kiaku bwabu"}, "Comprendre": {"en": "Understanding", "pt": "Compreender", "ln": "Kososola", "sw": "Kuelewa", "lu": "Kupetulula", "kg": "Bakula"}, "Qu'est-ce que le": {"en": "What Is", "pt": "O Que É o", "ln": "Nini ezali", "sw": "Ni Nini", "lu": "Ntu tshidi", "kg": "Nki i"}, "baptême ?": {"en": "Baptism?", "pt": "Batismo?", "ln": "libatisi ?", "sw": "Ubatizo?", "lu": "dibatiza ?", "kg": "botama?"}, "Un acte d'obéissance": {"en": "An Act of Obedience", "pt": "Um Ato de Obediência", "ln": "Ekela ya botosi", "sw": "Tendo la Utii", "lu": "Mvangu wa lemvokolo", "kg": "Mvangu wa lemvokolo"}, "Jésus lui-même a été baptisé et nous invite à faire de même. C'est une réponse d'obéissance à la Parole de Dieu, un acte de foi concret et visible.": {"en": "Jesus himself was baptized and invites us to do the same. It is a response of obedience to the Word of God, a concrete and visible act of faith.", "pt": "O próprio Jesus foi batizado e nos convida a fazer o mesmo. É uma resposta de obediência à Palavra de Deus, um ato de fé concreto e visível.", "ln": "Yesu ye moko azwaki libatisi mpe abengisaka biso tosala ndenge moko. Ezali eyano ya botosi na Liloba ya Nzambe, ekela ya kondima oyo emonanaka.", "sw": "Yesu mwenyewe alibatizwa na anatualika tufanye vivyo hivyo. Ni jibu la utii kwa Neno la Mungu, tendo la imani linaloonekana wazi.", "lu": "Yezu nkayende wakabatizibua ne udi utubikila bua tuenze bualu bumue. Mmandamuna a lemvokolo ku Dîyi dia Nzambi, mvangu wa ditabuja udi umueneka.", "kg": "Yezu niandi veka wubatuka ye ukutubikidi mu vanga bobo. I mvutu a lemvokolo ku Diambu dia Nzambi, mvangu wa minu wumonika."}, "Mort & Résurrection": {"en": "Death & Resurrection", "pt": "Morte e Ressurreição", "ln": "Liwa & Bosekwi", "sw": "Kifo na Ufufuo", "lu": "Lufu ne Dibika", "kg": "Lufwa ye Lufulukusu"}, "L'immersion symbolise la mort au péché et la résurrection à une nouvelle vie en Christ. L'eau représente la purification et le renouveau total.": {"en": "Immersion symbolizes death to sin and resurrection to a new life in Christ. Water represents purification and total renewal.", "pt": "A imersão simboliza a morte para o pecado e a ressurreição para uma nova vida em Cristo. A água representa a purificação e a renovação total.", "ln": "Kozindisama na mai emonisi liwa ya lisumu mpe bosekwi na bomoi ya sika kati na Klisto. Mai emonisi bopetoli mpe bobongwani ya mobimba.", "sw": "Kuzamishwa majini kunaashiria kifo cha dhambi na ufufuo kwenye maisha mapya katika Kristo. Maji yanawakilisha utakaso na upya kamili.", "lu": "Kunyibidila mu mâyi kudi kuleja lufu lua bubi ne dibika mu muoyo mupia mu Kristo. Mâyi adi aleja disukulula ne dibadika dijima.", "kg": "Kubuika mu nlangu kusonganga lufwa lua disumu ye lufulukusu mu luzingu luampa mu Kristu. Nlangu usongele vedisa ye kitulusu kimvimba."}, "Témoignage public": {"en": "Public Testimony", "pt": "Testemunho Público", "ln": "Litatoli ya polele", "sw": "Ushuhuda wa Hadharani", "lu": "Bumanyi bua batu bonso", "kg": "Kimbangi kia batu boso"}, "Le baptême est une déclaration publique de votre foi. Vous dites au monde entier : « J'appartiens à Christ et je choisis de le suivre. »": {"en": "Baptism is a public declaration of your faith. You are telling the whole world: \"I belong to Christ and I choose to follow Him.\"", "pt": "O batismo é uma declaração pública da sua fé. Você diz ao mundo inteiro: \"Eu pertenço a Cristo e escolho segui-Lo.\"", "ln": "Libatisi ezali elobeli ya polele ya kondima na yo. Ozali koloba na mokili mobimba : « Nazali ya Klisto mpe naponi kolanda Ye. »", "sw": "Ubatizo ni tamko la hadharani la imani yako. Unauambia ulimwengu wote: \"Mimi ni wa Kristo na ninachagua kumfuata.\"", "lu": "Dibatiza didi muambila wa batu bonso wa ditabuja diebe. Udi wamba kudi bulongo bujima : « Ndi wa Kristo ne ndi musungule kumulonda. »", "kg": "Botama i ntubulu a batu boso a minu kiaku. Wena kamba nza yamvimba: « Ndi wa Kristu ye ndisobuidi kunlanda. »"}, "Le parcours": {"en": "The Journey", "pt": "O Percurso", "ln": "Nzela", "sw": "Safari", "lu": "Njila", "kg": "Nzila"}, "01": {"en": "01", "pt": "01", "ln": "01", "sw": "01", "lu": "01", "kg": "01"}, "Inscription": {"en": "Registration", "pt": "Inscrição", "ln": "Bokomisi nkombo", "sw": "Usajili", "lu": "Difundisha dîna", "kg": "Sonikinu"}, "Remplissez le formulaire ci-dessous. Notre équipe vous contactera pour confirmer votre inscription et répondre à vos questions.": {"en": "Fill out the form below. Our team will contact you to confirm your registration and answer your questions.", "pt": "Preencha o formulário abaixo. Nossa equipe entrará em contato para confirmar sua inscrição e responder às suas perguntas.", "ln": "Tondisa fomilere oyo ezali na se. Ekipe na biso ekobenga yo mpo na kondimisa bokomisi nkombo na yo mpe koyanola na mituna na yo.", "sw": "Jaza fomu iliyo hapa chini. Timu yetu itawasiliana nawe kuthibitisha usajili wako na kujibu maswali yako.", "lu": "Wuja fomo udi muinshi eu. Tshisumbu tshietu netshikuakule bua kujadika difundisha diebe ne kuandamuna nkonko yebe.", "kg": "Fuana fomu widi kuna nsi. Kimvuka kieto kiela kusolula mu kukumina sonikinu kiaku ye vutula nsangu ziaku."}, "02": {"en": "02", "pt": "02", "ln": "02", "sw": "02", "lu": "02", "kg": "02"}, "Cours de préparation": {"en": "Preparation Course", "pt": "Curso de Preparação", "ln": "Kelasi ya bosaleli", "sw": "Kozi ya Maandalizi", "lu": "Tshikolo tshia dilongesha", "kg": "Longoka kia bubongisu"}, "Participez à notre cours de préparation au baptême pour comprendre le sens profond de cet acte et vous y préparer spirituellement.": {"en": "Take part in our baptism preparation course to understand the deep meaning of this act and prepare yourself spiritually.", "pt": "Participe do nosso curso de preparação para o batismo para entender o significado profundo deste ato e se preparar espiritualmente.", "ln": "Sangana na kelasi na biso ya bosaleli ya libatisi mpo na kososola ntina ya bozindo ya ekela oyo mpe komibongisa na molimo.", "sw": "Shiriki katika kozi yetu ya maandalizi ya ubatizo kuelewa maana ya kina ya tendo hili na kujiandaa kiroho.", "lu": "Wisangana ne tshikolo tshietu tshia dilongesha dia dibatiza bua kupetulula tshiena tshia bunene tshia mvangu eu ne kudilongesha mu nyuma.", "kg": "Kutakana ye longoka kieto kia bubongisu bua botama mu bakula tsundu yinene ya mvangu wowu ye kukubongisa mu mpeve."}, "03": {"en": "03", "pt": "03", "ln": "03", "sw": "03", "lu": "03", "kg": "03"}, "La cérémonie": {"en": "The Ceremony", "pt": "A Cerimônia", "ln": "Molulu", "sw": "Sherehe", "lu": "Fete", "kg": "Nkembo"}, "Vivez ce moment solennel entouré de votre famille spirituelle.": {"en": "Experience this solemn moment surrounded by your spiritual family.", "pt": "Viva este momento solene rodeado por sua família espiritual.", "ln": "Bika ntango oyo ya lokumu, ozingelami na libota na yo ya molimo.", "sw": "Ishi wakati huu mzito ukiwa umezungukwa na familia yako ya kiroho.", "lu": "Enza tshikondi etshi tshia bunene, muzungibue ne dîku diebe dia mu nyuma.", "kg": "Zinga thangu yayi yinlongo, muzungulukusu kua dibuta diaku dia mu mpeve."}, "04": {"en": "04", "pt": "04", "ln": "04", "sw": "04", "lu": "04", "kg": "04"}, "Nouvelle vie": {"en": "New Life", "pt": "Nova Vida", "ln": "Bomoi ya sika", "sw": "Maisha Mapya", "lu": "Muoyo mupia", "kg": "Luzingu luampa"}, "Après votre baptême, intégrez pleinement la vie de l'église, et grandissez dans votre foi.": {"en": "After your baptism, fully integrate into church life, and grow in your faith.", "pt": "Após o seu batismo, integre-se plenamente na vida da igreja e cresça na sua fé.", "ln": "Sima ya libatisi na yo, kota mobimba na bomoi ya lingomba, mpe kola na kondima na yo.", "sw": "Baada ya ubatizo wako, jiunge kikamilifu na maisha ya kanisa, na ukue katika imani yako.", "lu": "Panyima pa dibatiza diebe, buela mujima mu muoyo wa dibundu, ne kola mu ditabuja diebe.", "kg": "Kunima kua botama kiaku, kota mvimba mu luzingu lua dibundu, ye yela mu minu kiaku."}, "« Celui qui croira et qui sera baptisé sera sauvé. »": {"en": "\"Whoever believes and is baptized will be saved.\"", "pt": "\"Quem crer e for batizado será salvo.\"", "ln": "« Moto oyo akondima mpe akozwa libatisi akobika. »", "sw": "\"Yeyote atakayeamini na kubatizwa ataokolewa.\"", "lu": "« Yeye udi ne bua kuitabuja ne kubatizibua neapandishibue. »", "kg": "« Konso muena kwikila ye botama wela vuluka. »"}, "— Marc 16:16": {"en": "— Mark 16:16", "pt": "— Marcos 16:16", "ln": "— Marako 16:16", "sw": "— Marko 16:16", "lu": "— Mâko 16:16", "kg": "— Malako 16:16"}, "Inscrivez-vous dès maintenant. Votre message sera envoyé directement via WhatsApp.": {"en": "Sign up now. Your message will be sent directly via WhatsApp.", "pt": "Inscreva-se agora mesmo. Sua mensagem será enviada diretamente via WhatsApp.", "ln": "Komisa nkombo na yo sikoyo. Nsango na yo ekokende na mbala moko na nzela ya WhatsApp.", "sw": "Jisajili sasa. Ujumbe wako utatumwa moja kwa moja kupitia WhatsApp.", "lu": "Difundisha dîna diebe mpindieu. Lumu luebe neluye anu pashishi ku WhatsApp.", "kg": "Sonika zina kiaku bwabu. Nsamu aku wela kwenda ngolo mu WhatsApp."}, "Cours de préparation inclus": {"en": "Preparation Course Included", "pt": "Curso de Preparação Incluído", "ln": "Kelasi ya bosaleli ekotami", "sw": "Kozi ya Maandalizi Imejumuishwa", "lu": "Tshikolo tshia dilongesha tshidi mu", "kg": "Longoka kia bubongisu kikotudi"}, "Accompagnement personnalisé": {"en": "Personalized Support", "pt": "Acompanhamento Personalizado", "ln": "Lisungi ya moto na moto", "sw": "Msindikizo wa Kibinafsi", "lu": "Diambuluisha dia nkayebe", "kg": "Lusadusu lua nkaka"}, "Âge": {"en": "Age", "pt": "Idade", "ln": "Mbula", "sw": "Umri", "lu": "Bidimu", "kg": "Mvu"}, "Avez-vous donné votre vie à Christ ?": {"en": "Have you given your life to Christ?", "pt": "Você já deu sua vida a Cristo?", "ln": "Osi opesi bomoi na yo epai ya Klisto ?", "sw": "Je, umeshatoa maisha yako kwa Kristo?", "lu": "Udi mumane kupesha muoyo webe kudi Kristo anyi ?", "kg": "Ngeye wuvana ye luzingu luaku kua Kristu?"}, "Message ou témoignage": {"en": "Message or Testimony", "pt": "Mensagem ou Testemunho", "ln": "Nsango to litatoli", "sw": "Ujumbe au Ushuhuda", "lu": "Lumu anyi bumanyi", "kg": "Nsamu voti kimbangi"}, "S'inscrire": {"en": "Sign Up", "pt": "Inscrever-se", "ln": "Komisa nkombo", "sw": "Jisajili", "lu": "Difundisha dîna", "kg": "Sonika zina"}, "Organisation & Structure": {"en": "Organization & Structure", "pt": "Organização e Estrutura", "ln": "Bokambami & Ndenge etongami", "sw": "Mpangilio na Muundo", "lu": "Bulongolodi ne Ntudulu", "kg": "Ndongolo ye Kivangulu"}, "Vie de": {"en": "Life of", "pt": "Vida da", "ln": "Bomoi ya", "sw": "Maisha ya", "lu": "Muoyo wa", "kg": "Luzingu lua"}, "l'Église": {"en": "the Church", "pt": "a Igreja", "ln": "lingomba", "sw": "Kanisa", "lu": "dibundu", "kg": "dibundu"}, "Chaque département et service est un maillon essentiel du corps de Christ. Ensemble, nous servons, grandissons et glorifions Dieu.": {"en": "Every department and service is an essential link in the body of Christ. Together, we serve, grow, and glorify God.", "pt": "Cada departamento e serviço é um elo essencial do corpo de Cristo. Juntos, servimos, crescemos e glorificamos a Deus.", "ln": "Ebongiseli na ebongiseli nyonso mpe mosala ezali eloko ya ntina mingi ya nzoto ya Klisto. Elongo, tosalaka, tokolaka mpe tokumisaka Nzambe.", "sw": "Kila idara na huduma ni kiungo muhimu cha mwili wa Kristo. Pamoja, tunatumika, tunakua na kumtukuza Mungu.", "lu": "Tshipande tshionso ne mudimu mmuvuadi wa mushindu munene wa mubidi wa Kristo. Pamue, tudi tuenza mudimu, tukola ne kutumbisha Nzambi.", "kg": "Konso phande ye kisalu i mfunu wa nitu ya Kristu. Va kimosi, tuena sala, yela ye kembisa Nzambi."}, "Titre II - Art. 5": {"en": "Title II - Art. 5", "pt": "Título II - Art. 5", "ln": "Motó II - Mokapo 5", "sw": "Kichwa II - Kifungu 5", "lu": "Mutu wa Bibidi II - Mukanda 5", "kg": "Ntu II - Mukanda 5"}, "Départements Sectoriels": {"en": "Sectoral Departments", "pt": "Departamentos Setoriais", "ln": "Ba département ya sikitele", "sw": "Idara za Kisekta", "lu": "Bipande bia Mikanda", "kg": "Zimpande za Zunga"}, "Ces départements assurent l'encadrement spirituel, moral et social de leurs membres, sous l'autorité pastorale.": {"en": "These departments provide spiritual, moral, and social oversight for their members, under pastoral authority.", "pt": "Esses departamentos garantem o acompanhamento espiritual, moral e social de seus membros, sob a autoridade pastoral.", "ln": "Ba département oyo ebatelaka bato na yango na ndenge ya molimo, ya bizaleli mpe ya bomoi, na se ya bokonzi ya bakambi.", "sw": "Idara hizi zinatoa uongozi wa kiroho, kimaadili na kijamii kwa wanachama wao, chini ya mamlaka ya kichungaji.", "lu": "Bipande ebi bidi bilombola bena mu nyuma, bikadilu ne tshisamba tshia bena babu, muinshi mua bukokeshi bua bafumu.", "kg": "Zimpande ziazi zinsungisanga mu mpeve, nsiku ye kimvuka kia bambuta zawu, muna luyalu lua basambi."}, "« Exhorte les vieillards... les jeunes femmes... les jeunes gens... »": {"en": "\"Encourage the older men... the young women... the young men...\"", "pt": "\"Exorta os anciãos... as mulheres jovens... os jovens...\"", "ln": "« Lendisa mibange... basi ya bilenge... bilenge mibali... »", "sw": "\"Waonye wazee... wanawake vijana... vijana wa kiume...\"", "lu": "« Kolesha bakulukulu... bakaji ba bansonga... bansonga ba balume... »", "kg": "« Longa bakulutu... bakento matoko... matoko ma bakala... »"}, "— Tite 2:1-8 · 1 Timothée 4:12": {"en": "— Titus 2:1-8 · 1 Timothy 4:12", "pt": "— Tito 2:1-8 · 1 Timóteo 4:12", "ln": "— Tito 2:1-8 · 1 Timote 4:12", "sw": "— Tito 2:1-8 · 1 Timotheo 4:12", "lu": "— Tito 2:1-8 · 1 Timote 4:12", "kg": "— Tito 2:1-8 · 1 Timote 4:12"}, "Département des Hommes": {"en": "Men's Department", "pt": "Departamento dos Homens", "ln": "Ebongiseli ya mibali", "sw": "Idara ya Wanaume", "lu": "Tshipande tshia balume", "kg": "Phande ya Bakala"}, "Dans le monde d'aujourd'hui, les églises qui sont fortes et en pleine croissance sont celles qui se tournent vers les hommes. Les recherches actuelles démontrent que lorsqu'un homme s'engage, toute sa famille suit généralement son exemple. Ce département encourage la maturité spirituelle et le leadership chrétien. Il est un pilier essentiel pour la stabilité de l'église.": {"en": "In today's world, churches that are strong and growing are those that turn towards men. Current research shows that when a man commits, his whole family generally follows his example. This department encourages spiritual maturity and Christian leadership. It is an essential pillar for the stability of the church.", "pt": "No mundo de hoje, as igrejas fortes e em pleno crescimento são as que se voltam para os homens. Pesquisas atuais mostram que quando um homem se compromete, toda a sua família geralmente segue o seu exemplo. Este departamento incentiva a maturidade espiritual e a liderança cristã. É um pilar essencial para a estabilidade da igreja.", "ln": "Na mokili ya lelo, mangomba oyo ezali makasi mpe ekolaka ezali oyo etalaka epai ya mibali. Boluki-luki ya lelo emonisi ete tango mobali amipesi, libota na ye mobimba elandaka ndakisa na ye. Ebongiseli oyo elendisaka bokoli ya molimo mpe bokambi ya boklisto. Ezali likonzi ya ntina mpo na kokangama ya lingomba.", "sw": "Katika ulimwengu wa leo, makanisa yenye nguvu na yanayokua ni yale yanayowageukia wanaume. Utafiti wa sasa unaonyesha kuwa mwanamume anapojitolea, familia yake yote kwa kawaida inafuata mfano wake. Idara hii inahimiza ukomavu wa kiroho na uongozi wa Kikristo. Ni nguzo muhimu kwa uthabiti wa kanisa.", "lu": "Mu bulongo bua lelu, mabundu adi makole ne akola ntshingu mmadi alangamina kudi balume. Bulongolodi bua mpindieu budi buleja ne padi mulume udipesha, dîku diende dijima didi dilonda tshilejilu tshiende. Tshipande etshi tshidi tshikolesha dikola dia mu nyuma ne bukokeshi bua bena Kristo. Ntshidi tshikuatshilu tshinene bua bujima bua dibundu.", "kg": "Mu nza ya lumbu kiaki, mabundu makole ye manlungu i mama malandanga bakala. Nlongoso ya lumbu kiaki isonganga ti kana bakala kudipesa, dibuta diandi dimvimba dilandanga mbandu andi. Phande yayi ilenda kolesa mfumu mu mpeve ye buyalu bu bakristu. I diyaya dinene mu diambu dia lulendo lua dibundu."}, "Département des Femmes": {"en": "Women's Department", "pt": "Departamento das Mulheres", "ln": "Ebongiseli ya basi", "sw": "Idara ya Wanawake", "lu": "Tshipande tshia bakaji", "kg": "Phande ya Bakento"}, "Ce département n'est pas un mouvement féministe mais un cadre spirituel d'échanges entre sœurs dans la foi. Les femmes y trouvent un espace pour se soutenir mutuellement et croître dans leur relation avec Dieu. Elles organisent des retraites, des temps de prière et des conférences édifiantes. Leur rôle est vital dans la transmission des valeurs chrétiennes.": {"en": "This department is not a feminist movement but a spiritual framework for exchange between sisters in the faith. Women find a space here to support each other and grow in their relationship with God. They organize retreats, prayer times, and edifying conferences. Their role is vital in passing on Christian values.", "pt": "Este departamento não é um movimento feminista, mas um quadro espiritual de trocas entre irmãs na fé. As mulheres encontram aqui um espaço para se apoiarem mutuamente e crescerem em seu relacionamento com Deus. Elas organizam retiros, momentos de oração e conferências edificantes. Seu papel é vital na transmissão dos valores cristãos.", "ln": "Ebongiseli oyo ezali mouvement ya bofeministe te kasi ezali esika ya molimo epai bandeko basi na kondima bakutanaka. Basi bazwaka wana esika ya kosungana mpe kokola na boyokani na bango na Nzambe. Babongisaka ba retraite, bantango ya losambo mpe ba conférence oyo etongaka. Mokumba na bango ezali ya ntina mingi mpo na kolekisa mitinda ya boklisto.", "sw": "Idara hii sio harakati ya kifeministi bali ni mfumo wa kiroho wa mawasiliano kati ya dada katika imani. Wanawake wanapata hapa nafasi ya kusaidiana na kukua katika uhusiano wao na Mungu. Wanapanga mafungo, nyakati za maombi na makongamano yenye kujenga. Jukumu lao ni muhimu katika kupitisha maadili ya Kikristo.", "lu": "Tshipande etshi kabiena tshisumbu tshia bakaji anu to kadi mmuaba wa mu nyuma wa kudisangisha munkatshi mua bana ba bakaji mu ditabuja. Bakaji badi bapeta mua kuambuluishangana ne kukola mu malanda abu ne Nzambi. Badi benza mishikamina, bikondi bia mulombela ne mabikilu adi mabakula. Mudimu wabu mmunene mu dijikula dia mikenji ya bena Kristo.", "kg": "Phande yayi kasi kimvuka kia zibakento ko kansi i fulu kia mpeve kia zithuadulu vakati kua bampangi za bakento mu minu. Bakento bambaka vava fulu kia kusadisana ye yela mu kithuadi kiawu ye Nzambi. Bawakananga makumbu, ntangu za sambu ye zinkutakanu zinlonga. Mfulu awu i nzaka mu kwenda kua mfunu mia bakristu."}, "Département de la Jeunesse": {"en": "Youth Department", "pt": "Departamento da Juventude", "ln": "Ebongiseli ya bilenge", "sw": "Idara ya Vijana", "lu": "Tshipande tshia bansonga", "kg": "Phande ya Matoko"}, "Les jeunes constituent la force vive de l'église et bénéficient d'un encadrement adapté. Ils participent à des activités spirituelles, sportives et sociales qui favorisent leur développement intégral. Le département vise à fortifier leur foi dans un monde rempli de défis. C'est un lieu d'épanouissement et de service pour Christ.": {"en": "Youth make up the vibrant force of the church and benefit from tailored guidance. They take part in spiritual, sporting, and social activities that promote their overall development. The department aims to strengthen their faith in a world full of challenges. It is a place of growth and service for Christ.", "pt": "Os jovens constituem a força viva da igreja e beneficiam de um acompanhamento adaptado. Eles participam de atividades espirituais, esportivas e sociais que favorecem seu desenvolvimento integral. O departamento visa fortalecer sua fé em um mundo cheio de desafios. É um lugar de crescimento e serviço para Cristo.", "ln": "Bilenge bazali makasi ya bomoi ya lingomba mpe bazwaka bokambami oyo ebongi na bango. Basanganaka na misala ya molimo, ya masano mpe ya bomoi oyo ekolisaka bango mobimba. Ebongiseli elukaka kolendisa kondima na bango na mokili etondi na mikakatano. Ezali esika ya bokoli mpe ya mosala mpo na Klisto.", "sw": "Vijana ni nguvu hai ya kanisa na wananufaika na uongozi unaowafaa. Wanashiriki katika shughuli za kiroho, michezo na kijamii zinazokuza maendeleo yao kamili. Idara hii inalenga kuimarisha imani yao katika ulimwengu uliojaa changamoto. Ni mahali pa ukuaji na huduma kwa Kristo.", "lu": "Bansonga mbadi bukole bua muoyo bua dibundu ne badi bapeta dilombola didi diakumbana nabu. Badi basangana mu bienzedi bia mu nyuma, masue ne tshisamba bidi bikolesha dikola diabu dijima. Tshipande etshi tshidi tshikeba bua kukolesha ditabuja diabu mu bulongo bujadika ntatu ya bungi. Mmuaba wa dikola ne mudimu bua Kristo.", "kg": "Matoko i ngolo yamoyo ya dibundu ye bambakanga lutwadusu lufwana yawu. Bena vanga mavanga ma mpeve, masumbani ye kimvuka bilenda kolesa nkolokoso yawu mvimba. Phande yayi izolele kolesa minu kiawu mu nza yifulukusu ntantu. I fulu kia yela ye kisalu mu diambu dia Kristu."}, "L'École de Dimanche est dédiée à l'éducation biblique des enfants dès leur bas âge. Elle enseigne les vérités de la Parole de Dieu à travers des méthodes simples et adaptées. Chaque enfant y apprend l'amour de Dieu et les valeurs chrétiennes essentielles. Les moniteurs veillent à leur croissance spirituelle et morale.": {"en": "Sunday School is dedicated to the biblical education of children from a young age. It teaches the truths of the Word of God through simple, tailored methods. Every child learns the love of God and essential Christian values there. The teachers watch over their spiritual and moral growth.", "pt": "A Escola Dominical é dedicada à educação bíblica das crianças desde tenra idade. Ela ensina as verdades da Palavra de Deus através de métodos simples e adaptados. Cada criança aprende ali o amor de Deus e os valores cristãos essenciais. Os monitores zelam pelo seu crescimento espiritual e moral.", "ln": "Kelasi ya Eyenga ebulisami mpo na mateya ya Biblia epai ya bana banda bomwana na bango. Eteyaka bosolo ya Liloba ya Nzambe na nzela ya mayele ya pete oyo ebongi. Mwana na mwana ayekolaka wana bolingo ya Nzambe mpe mitinda ya ntina ya boklisto. Balakisi bakengelaka bokoli na bango ya molimo mpe ya bizaleli.", "sw": "Shule ya Jumapili imejitolea kwa elimu ya kibiblia ya watoto tangu utotoni. Inafundisha kweli za Neno la Mungu kupitia mbinu rahisi zinazofaa. Kila mtoto anajifunza huko upendo wa Mungu na maadili muhimu ya Kikristo. Waalimu wanasimamia ukuaji wao wa kiroho na kimaadili.", "lu": "Tshikolo tshia Dimanche tshidi tshipeshibue bua dilongesha dia Bible dia bana katshia ku bumuana buabu. Tshidi tshilongesha bulelela bua Dîyi dia Nzambi ku diambu dia mishindu mipepele idi ikumbana. Muana yonso udi ulongela kunku dinanga dia Nzambi ne mikenji minene ya bena Kristo. Balongeshi badi bakengela dikola diabu dia mu nyuma ne dikadilu.", "kg": "Nkangu ya Lumingu widi wavana mu longoka kua Nkand'a Nzambi kua bana tona lezi kiawu. Wilonganga makieleka ma Diambu dia Nzambi mu bikubu biphasi ye bifwana. Konso mwana wela longukanga kuna luzolo lua Nzambi ye mfunu mia bakristu mankaka. Minlongi milenda tala nkolokoso au ya mpeve ye nsiku."}, "Titre II - Art. 6": {"en": "Title II - Art. 6", "pt": "Título II - Art. 6", "ln": "Motó II - Mokapo 6", "sw": "Kichwa II - Kifungu 6", "lu": "Mutu wa Bibidi II - Mukanda 6", "kg": "Ntu II - Mukanda 6"}, "Département de la Musique": {"en": "Music Department", "pt": "Departamento de Música", "ln": "Ebongiseli ya miziki", "sw": "Idara ya Muziki", "lu": "Tshipande tshia Musika", "kg": "Phande ya Miziki"}, "Chargé de la louange et de l'adoration lors des cultes, il veille à la conformité doctrinale des chants et à la sainteté dans le culte.": {"en": "Responsible for praise and worship during services, it ensures the doctrinal soundness of the songs and holiness in worship.", "pt": "Encarregado do louvor e da adoração durante os cultos, zela pela conformidade doutrinária dos cânticos e pela santidade no culto.", "ln": "Ezali na mokumba ya lisanzoli mpe losambo na tango ya masanga, ekengelaka bosembo ya mateya ya banzembo mpe bosantu na losambo.", "sw": "Ikiwa na jukumu la sifa na ibada wakati wa ibada, inahakikisha usahihi wa mafundisho ya nyimbo na utakatifu katika ibada.", "lu": "Tshidi ne mudimu wa disanka ne mulombela mu bikondi bia bisumbu, tshidi tshikengela buakane bua malongesha a nyimbo ne bunsantu mu mulombela.", "kg": "Kina kisalu kia nzitusu ye lusambulu mu ntangu za lusambulu, kilenda tala kieleka kia malongi ma nkunga ye vedila mu lusambulu."}, "« Dieu est Esprit, et il faut que ceux qui l'adorent l'adorent en esprit et en vérité. »": {"en": "\"God is Spirit, and those who worship him must worship in spirit and truth.\"", "pt": "\"Deus é Espírito, e é necessário que os que o adoram o adorem em espírito e em verdade.\"", "ln": "« Nzambe azali Molimo, mpe basengeli komipesa na losambo na molimo mpe na bosolo. »", "sw": "\"Mungu ni Roho, na wale wamwabuduo yampasa wamwabudu katika roho na kweli.\"", "lu": "« Nzambi mmunyuma, ne badi ne bua kumusambila mu nyuma ne mu bulelela. »", "kg": "« Nzambi i Mpeve, ye bansambila fweti kunsambila mu mpeve ye mu kieleka. »"}, "— Jean 4:23-24 · 1 Chroniques 25": {"en": "— John 4:23-24 · 1 Chronicles 25", "pt": "— João 4:23-24 · 1 Crônicas 25", "ln": "— Yoane 4:23-24 · 1 Bakronika 25", "sw": "— Yohana 4:23-24 · 1 Mambo ya Nyakati 25", "lu": "— Yowano 4:23-24 · 1 Nkuadi 25", "kg": "— Yoane 4:23-24 · 1 Kuronika 25"}, "Département de Musique": {"en": "Music Department", "pt": "Departamento de Música", "ln": "Ebongiseli ya miziki", "sw": "Idara ya Muziki", "lu": "Tshipande tshia Musika", "kg": "Phande ya Miziki"}, "Le département de la musique anime les cultes et contribue à créer une atmosphère de louange. Les choristes et musiciens sont engagés dans un ministère de consécration. Ils préparent les cœurs à recevoir la Parole par des chants inspirés. Le groupe œuvre aussi dans des concerts et veillées spirituelles. Leur mission est d'élever le Nom de Jésus-Christ à travers la musique.": {"en": "The music department animates the services and helps create an atmosphere of praise. The choir members and musicians are engaged in a ministry of consecration. They prepare hearts to receive the Word through inspired songs. The group also works in concerts and spiritual vigils. Their mission is to lift up the Name of Jesus Christ through music.", "pt": "O departamento de música anima os cultos e contribui para criar uma atmosfera de louvor. Os coristas e músicos estão engajados em um ministério de consagração. Eles preparam os corações para receber a Palavra através de cânticos inspirados. O grupo também atua em concertos e vigílias espirituais. Sua missão é exaltar o Nome de Jesus Cristo através da música.", "ln": "Ebongiseli ya miziki epesaka bomoi na masanga mpe esalisaka mpo na kokela molongo ya lisanzoli. Bayembi mpe basani ya miziki bamipesi na mosala ya kokabwana. Babongisaka mitema mpo na koyamba Liloba na nzela ya banzembo ya kolendisama. Etuluku esalaka mpe na ba concert mpe basusuku ya molimo. Mokumba na bango ezali kotombola Nkombo ya Yesu-Klisto na nzela ya miziki.", "sw": "Idara ya muziki inachangamsha ibada na kusaidia kuunda mazingira ya sifa. Waimbaji na wanamuziki wamejitolea katika huduma ya kujiweka wakfu. Wanaandaa mioyo kupokea Neno kupitia nyimbo zenye kutia moyo. Kikundi pia kinafanya kazi katika tamasha na makesha ya kiroho. Dhamira yao ni kukiinua Jina la Yesu Kristo kupitia muziki.", "lu": "Tshipande tshia musika tshidi tshipesha muoyo mu bisumbu ne tshiambuluisha mu kufuka diakalenga dia disanka. Bimbi ne bena musika badi badipesha mu mudimu wa kudipesha. Badi balongesha mitshima bua kutambula Dîyi ku diambu dia nyimbo idi ikolesha. Tshisumbu tshidi tshienza kabidi mu bikondi bia musika ne mishindu ya mu nyuma. Mudimu wabu mmuvumisha Dîna dia Yezu-Kristo ku diambu dia musika.", "kg": "Phande ya miziki yilenda pesa moyo mu lusambulu ye sadisa vanga diaka dia nzitusu. Bimbi ye bena miziki bena mu kisalu kia kudipesa. Bena bongesa mintima mu tambula Diambu mu nkunga zinlembo kolesa. Kimvuka kilenda mpe sala mu bikondi bia miziki ye masikamu ma mpeve. Kisalu kiawu i tombula Zina dia Yezu-Kristu mu miziki."}, "Titre II - Art. 7": {"en": "Title II - Art. 7", "pt": "Título II - Art. 7", "ln": "Motó II - Mokapo 7", "sw": "Kichwa II - Kifungu 7", "lu": "Mutu wa Bibidi II - Mukanda 7", "kg": "Ntu II - Mukanda 7"}, "Département de l'Intercession": {"en": "Intercession Department", "pt": "Departamento de Intercessão", "ln": "Ebongiseli ya kobondela", "sw": "Idara ya Uombezi", "lu": "Tshipande tshia mulombela", "kg": "Phande ya Sambu"}, "Ce département assure la couverture spirituelle permanente de l'église par la prière.": {"en": "This department provides ongoing spiritual covering for the church through prayer.", "pt": "Este departamento garante a cobertura espiritual permanente da igreja através da oração.", "ln": "Ebongiseli oyo ebatelaka lingomba na molimo tango nyonso na nzela ya losambo.", "sw": "Idara hii inatoa ulinzi wa kiroho wa kudumu wa kanisa kupitia maombi.", "lu": "Tshipande etshi tshidi tshilama dibundu mu nyuma tshikondi tshionso ku diambu dia mulombela.", "kg": "Phande yayi ilenda sunga dibundu mu mpeve thangu zawonso mu nzila ya sambu."}, "« Priez sans cesse. »": {"en": "\"Pray without ceasing.\"", "pt": "\"Orai sem cessar.\"", "ln": "« Bobondela ntango nyonso. »", "sw": "\"Ombeni bila kukoma.\"", "lu": "« Lombela tshikondi tshionso. »", "kg": "« Samba ku kambu vonga. »"}, "— 1 Thessaloniciens 5:17 · Ézéchiel 22:30": {"en": "— 1 Thessalonians 5:17 · Ezekiel 22:30", "pt": "— 1 Tessalonicenses 5:17 · Ezequiel 22:30", "ln": "— 1 Batesalonika 5:17 · Ezekiele 22:30", "sw": "— 1 Wathesalonike 5:17 · Ezekieli 22:30", "lu": "— 1 Tesalonika 5:17 · Nzekele 22:30", "kg": "— 1 Tesalonika 5:17 · Ezekiele 22:30"}, "Prière & Intercession": {"en": "Prayer & Intercession", "pt": "Oração e Intercessão", "ln": "Losambo & Kobondela", "sw": "Maombi na Uombezi", "lu": "Mulombela ne dibondela", "kg": "Sambu ye Lombelo"}, "Un groupe de prière dévoué qui intercède pour l'église, la nation et les besoins de nos membres. Ils se tiennent dans la brèche, veillant en prière pour que la grâce de Dieu se répande sur chaque vie.": {"en": "A dedicated prayer group that intercedes for the church, the nation, and the needs of our members. They stand in the gap, watching in prayer so that God's grace may pour out on every life.", "pt": "Um grupo de oração dedicado que intercede pela igreja, pela nação e pelas necessidades dos nossos membros. Eles se colocam na brecha, vigiando em oração para que a graça de Deus se derrame sobre cada vida.", "ln": "Etuluku ya losambo oyo emipesi mobimba mpo na kobondela mpo na lingomba, ekolo mpe bamposa ya bandimi na biso. Batelemaka na esika ya kokabwana, bakengelaka na losambo mpo ngolu ya Nzambe esopana likolo ya bomoi na bomoi.", "sw": "Kikundi cha maombi kilichojitolea kinachoombea kanisa, taifa, na mahitaji ya wanachama wetu. Wanasimama katika pengo, wakikesha katika maombi ili neema ya Mungu imwagike juu ya kila maisha.", "lu": "Tshisumbu tshia mulombela tshidipesha bua kulombela bua dibundu, tshisamba tshionso ne majinga a bena babu. Badi bimana mu muaba, batekesha mu mulombela bua ngasa wa Nzambi ukale utangala pa muoyo yonso.", "kg": "Kimvuka kia sambu kidipana mu lomba mu diambu dia dibundu, tsi ye mfunu mia bambuta zeto. Bena telama mu vata, bakeba mu sambu mu diambu nlemvo wa Nzambi wudukuka pa luzingu loso."}, "Titre II - Art. 8": {"en": "Title II - Art. 8", "pt": "Título II - Art. 8", "ln": "Motó II - Mokapo 8", "sw": "Kichwa II - Kifungu 8", "lu": "Mutu wa Bibidi II - Mukanda 8", "kg": "Ntu II - Mukanda 8"}, "Département de l'Évangélisation": {"en": "Evangelism Department", "pt": "Departamento de Evangelismo", "ln": "Ebongiseli ya bosakoli", "sw": "Idara ya Uinjilishaji", "lu": "Tshipande tshia Evanjeliyo", "kg": "Phande ya Evanjelizasio"}, "Sa mission : gagner des âmes, l'accueil et le suivi spirituel des nouveaux convertis.": {"en": "Its mission: to win souls, to welcome and spiritually follow up with new converts.", "pt": "Sua missão: ganhar almas, acolher e acompanhar espiritualmente os novos convertidos.", "ln": "Mokumba na yango : kolonga milimo, koyamba mpe kolanda na molimo bato ya sika oyo babongwani.", "sw": "Dhamira yake: kuokoa roho, kupokea na kufuatilia kiroho waongofu wapya.", "lu": "Mudimu wende: kupeta mioyo, kuakidila ne kulonda mu nyuma bena bapiabipia bashintuluka.", "kg": "Kisalu kiandi: baka mioyo, tambula ye landa mu mpeve bena mpa balukidi."}, "« Allez, faites de toutes les nations des disciples... »": {"en": "\"Go and make disciples of all nations...\"", "pt": "\"Ide, fazei discípulos de todas as nações...\"", "ln": "« Bokende, bokomisa bikolo nyonso bayekoli... »", "sw": "\"Nendeni, mkafanye mataifa yote kuwa wanafunzi...\"", "lu": "« Yayi, wenzeji bisamba bionso balongoji... »", "kg": "« Yenda, vanga makanda moso balongoki... »"}, "— Matthieu 28:19-20 · Actes 1:8": {"en": "— Matthew 28:19-20 · Acts 1:8", "pt": "— Mateus 28:19-20 · Atos 1:8", "ln": "— Matai 28:19-20 · Misala 1:8", "sw": "— Mathayo 28:19-20 · Matendo 1:8", "lu": "— Matayo 28:19-20 · Bienzedi 1:8", "kg": "— Matai 28:19-20 · Bisalu 1:8"}, "Évangélisation": {"en": "Evangelism", "pt": "Evangelismo", "ln": "Bosakoli", "sw": "Uinjilishaji", "lu": "Evanjeliyo", "kg": "Evanjelizasio"}, "Ce département est au cœur de la mission de l'église. Il organise des campagnes d'évangélisation, accueille les nouveaux convertis et les accompagne dans leur intégration ecclésiale. Chaque âme gagnée est une victoire pour le Royaume de Dieu.": {"en": "This department is at the heart of the church's mission. It organizes evangelism campaigns, welcomes new converts, and helps them integrate into church life. Every soul won is a victory for the Kingdom of God.", "pt": "Este departamento está no centro da missão da igreja. Ele organiza campanhas de evangelismo, acolhe os novos convertidos e os acompanha na sua integração eclesial. Cada alma ganha é uma vitória para o Reino de Deus.", "ln": "Ebongiseli oyo ezali na motema ya mokumba ya lingomba. Ebongisaka ba campagne ya bosakoli, eyambaka bato ya sika oyo babongwani mpe elandaka bango na bokoti na bango na lingomba. Molimo moko na moko oyo elongami ezali elonga mpo na Bokonzi ya Nzambe.", "sw": "Idara hii iko katikati ya dhamira ya kanisa. Inapanga kampeni za uinjilishaji, kuwapokea waongofu wapya na kuwasindikiza katika kujumuika kwao kikanisa. Kila roho iliyopatikana ni ushindi kwa Ufalme wa Mungu.", "lu": "Tshipande etshi tshidi mu tshianza tshia mudimu wa dibundu. Tshidi tshilongesha ba campagne ya Evanjeliyo, tshiakidila bena bapiabipia bashintuluka ne kubalondesha mu kudisangisha kuabu ne dibundu. Muoyo yonso mupetibue mmudienga bua Bukalenge bua Nzambi.", "kg": "Phande yayi i muna mfulu a kisalu kia dibundu. Yilenda longesa bikubu bia evanjelizasio, tambula bena mpa balukidi ye kubalanda mu kuwakana kuawu ye dibundu. Konso mwoyo wubaka i ndungunu mu Kimfumu kia Nzambi."}, "Titre III - Art. 9 à 15": {"en": "Title III - Art. 9 to 15", "pt": "Título III - Art. 9 a 15", "ln": "Motó III - Mikapo 9 kino 15", "sw": "Kichwa III - Vifungu 9 hadi 15", "lu": "Mutu wa Bibidi III - Mikanda 9 too ne 15", "kg": "Ntu III - Mikanda 9 too na 15"}, "Services Spécialisés": {"en": "Specialized Services", "pt": "Serviços Especializados", "ln": "Misala ya bokoko", "sw": "Huduma Maalum", "lu": "Bisadidi bia bunene", "kg": "Bisalu bia Kikeka"}, "Des services dédiés pour répondre aux besoins spécifiques de la communauté dans la justice, l'ordre et l'amour.": {"en": "Dedicated services to meet the specific needs of the community in justice, order, and love.", "pt": "Serviços dedicados para responder às necessidades específicas da comunidade na justiça, na ordem e no amor.", "ln": "Misala oyo emipesi mpo na koyanola na bamposa ya sikisiki ya lisanga na bosembo, na molongo mpe na bolingo.", "sw": "Huduma zilizojitolea kukidhi mahitaji mahususi ya jumuiya katika haki, utaratibu na upendo.", "lu": "Bisadidi bidipesha bua kuandamuna majinga makole a tshisumbu mu buakane, muendo ne dinanga.", "kg": "Bisalu bidipana mu vutula mfunu mia kikeka mia kimvuka mu lunungu, ndonga ye luzolo."}, "« Que tout se fasse avec bienséance et avec ordre. »": {"en": "\"Let all things be done decently and in order.\"", "pt": "\"Que tudo se faça com decência e ordem.\"", "ln": "« Tika ete makambo nyonso esalema na lokumu mpe na molongo. »", "sw": "\"Vitu vyote na vifanyike kwa adabu na kwa utaratibu.\"", "lu": "« Malu onso enzeke ne bulame ne muendo. »", "kg": "« Bika mamu moso mavangama mu mfwana ye ndonga. »"}, "— 1 Corinthiens 14:40": {"en": "— 1 Corinthians 14:40", "pt": "— 1 Coríntios 14:40", "ln": "— 1 Bakorinti 14:40", "sw": "— 1 Wakorintho 14:40", "lu": "— 1 Kolinto 14:40", "kg": "— 1 Kolinto 14:40"}, "Service de Protocole": {"en": "Protocol Service", "pt": "Serviço de Protocolo", "ln": "Mosala ya protocole", "sw": "Huduma ya Itifaki", "lu": "Mudimu wa Protocole", "kg": "Kisalu kia Protokoli"}, "Art. 14 — Éphésiens 5:22-33": {"en": "Art. 14 — Ephesians 5:22-33", "pt": "Art. 14 — Efésios 5:22-33", "ln": "Mokapo 14 — Baefese 5:22-33", "sw": "Kifungu 14 — Waefeso 5:22-33", "lu": "Mukanda 14 — Efeso 5:22-33", "kg": "Mukanda 14 — Efeso 5:22-33"}, "Le service de protocole accueille chaque fidèle avec chaleur et respect. Il organise la disposition des salles et veille au bon déroulement des cultes. Ses membres assistent les responsables et assurent une bonne organisation. Ils incarnent l'ordre, l'hospitalité et le respect dans la maison de Dieu.": {"en": "The protocol service welcomes every believer with warmth and respect. It organizes the arrangement of rooms and ensures services run smoothly. Its members assist leaders and ensure good organization. They embody order, hospitality, and respect in the house of God.", "pt": "O serviço de protocolo acolhe cada fiel com calor e respeito. Ele organiza a disposição das salas e zela pelo bom andamento dos cultos. Seus membros auxiliam os responsáveis e garantem uma boa organização. Eles encarnam a ordem, a hospitalidade e o respeito na casa de Deus.", "ln": "Mosala ya protocole eyambaka mondimi na mondimi na bolingo mpe na limemya. Ebongisaka bisika ya bandako mpe ekengelaka ete masanga esalema malamu. Bato na yango basungaka bakambi mpe bakengelaka bobongisi malamu. Bamonisaka molongo, boyambi mpe limemya na ndako ya Nzambe.", "sw": "Huduma ya itifaki inapokea kila muumini kwa ukarimu na heshima. Inapanga mpangilio wa vyumba na kuhakikisha ibada zinaendelea vizuri. Wanachama wake wanasaidia viongozi na kuhakikisha mpangilio mzuri. Wanadhihirisha utaratibu, ukarimu na heshima katika nyumba ya Mungu.", "lu": "Mudimu wa protocole udi wakidila muena kuitabuja yonso ne dianga ne bunême. Udi ulongesha mushindu wa bimenga ne kukengela bua bisumbu benze bimpe. Bena mudimu badi bambuluisha bakulu ne kujadika bulongolodi bumpe. Badi baleja muendo, buakidila ne bunême mu nzubu wa Nzambi.", "kg": "Kisalu kia protokoli kilenda tambula konso nkwikizi mu luzolo ye lukinzu. Kilenda longesa nsalulu ya bimvunda ye tala mbote ya lusambulu. Bena kisalu bena sadisa minunu ye kumina bulongo bumbote. Bena songa ndonga, kiakusu ye lukinzu mu nzo ya Nzambi."}, "Service de Sécurité": {"en": "Security Service", "pt": "Serviço de Segurança", "ln": "Mosala ya sekurite", "sw": "Huduma ya Usalama", "lu": "Mudimu wa lulama", "kg": "Kisalu kia Lulendo"}, "Art. 15 — Néhémie 4:9 · Psaume 127:1": {"en": "Art. 15 — Nehemiah 4:9 · Psalm 127:1", "pt": "Art. 15 — Neemias 4:9 · Salmo 127:1", "ln": "Mokapo 15 — Neyemia 4:9 · Nzembo 127:1", "sw": "Kifungu 15 — Nehemia 4:9 · Zaburi 127:1", "lu": "Mukanda 15 — Nehemiya 4:9 · Misambu 127:1", "kg": "Mukanda 15 — Nehemiya 4:9 · Nkunga 127:1"}, "Le service de sécurité garantit l'ordre et la discipline durant toutes les activités. Ses membres veillent à la protection des biens et des personnes. Ils assurent un environnement sûr et paisible pour la louange et l'enseignement.": {"en": "The security service ensures order and discipline during all activities. Its members watch over the protection of property and people. They ensure a safe and peaceful environment for worship and teaching.", "pt": "O serviço de segurança garante a ordem e a disciplina durante todas as atividades. Seus membros zelam pela proteção de bens e pessoas. Eles garantem um ambiente seguro e tranquilo para o louvor e o ensino.", "ln": "Mosala ya sekurite ekengelaka molongo mpe discipline na tango ya misala nyonso. Bato na yango bakengelaka bozwi mpe bato. Bakengelaka esika ya kimia mpe ya libateli mpo na lisanzoli mpe mateya.", "sw": "Huduma ya usalama inahakikisha utaratibu na nidhamu wakati wa shughuli zote. Wanachama wake wanasimamia ulinzi wa mali na watu. Wanahakikisha mazingira salama na ya amani kwa sifa na mafundisho.", "lu": "Mudimu wa lulama udi ujadika muendo ne dishinda mu bienzedi bionso. Bena mudimu badi bakengela dilama dia bintu ne bantu. Badi bajadika muaba wa disanka ne ditalala bua disanka ne dilongesha.", "kg": "Kisalu kia lulendo kilenda kumina ndonga ye lulongolo mu mavanga moso. Bena kisalu bena tala lusadusu lua bima ye batu. Bena kumina fulu kia lulendo ye ngemba mu diambu dia nzitusu ye malongi."}, "Service de Média": {"en": "Media Service", "pt": "Serviço de Mídia", "ln": "Mosala ya média", "sw": "Huduma ya Vyombo vya Habari", "lu": "Mudimu wa Média", "kg": "Kisalu kia Média"}, "Art. 13 — Habacuc 2:2 · Psaume 68:12": {"en": "Art. 13 — Habakkuk 2:2 · Psalm 68:12", "pt": "Art. 13 — Habacuque 2:2 · Salmo 68:12", "ln": "Mokapo 13 — Abakuku 2:2 · Nzembo 68:12", "sw": "Kifungu 13 — Habakuki 2:2 · Zaburi 68:12", "lu": "Mukanda 13 — Habakuki 2:2 · Misambu 68:12", "kg": "Mukanda 13 — Abakuki 2:2 · Nkunga 68:12"}, "Le service média prend en charge la communication et la diffusion des cultes. Il comprend la presse écrite, l'équipe technique audio-visuelle et les plateformes numériques. Grâce aux outils modernes, il propage l'évangile au-delà des murs de l'église.": {"en": "The media service handles communication and broadcasting of the services. It includes the written press, the audio-visual technical team, and digital platforms. Thanks to modern tools, it spreads the gospel beyond the walls of the church.", "pt": "O serviço de mídia cuida da comunicação e da transmissão dos cultos. Inclui a imprensa escrita, a equipe técnica audiovisual e as plataformas digitais. Graças às ferramentas modernas, propaga o evangelho além das paredes da igreja.", "ln": "Mosala ya média ezwaka mokumba ya bosaleli mpe kopalanganisa masanga. Ekokani na presse écrite, ekipe ya ba technique ya audio-visuel mpe ba plateforme ya nimero. Na nzela ya bisaleli ya lelo, epalanganisi Nsango Malamu libanda ya bamir ya lingomba.", "sw": "Huduma ya vyombo vya habari inashughulikia mawasiliano na urushaji wa ibada. Inajumuisha vyombo vya habari vilivyoandikwa, timu ya kiufundi ya sauti na picha, na majukwaa ya kidijitali. Kwa msaada wa zana za kisasa, inaeneza injili zaidi ya kuta za kanisa.", "lu": "Mudimu wa média udi utuadija diakulu ne kutangalaja bisumbu. Udi ne mikanda idi ifundibue, tshisumbu tshia technique tshia audio-visuel ne bipatelu bia numelike. Ku diambu dia bikuata bipia, udi utangalaja Lumu Luimpe kupita miba ya dibundu.", "kg": "Kisalu kia média kilenda sunga makutakanu ye kutangalasa lusambulu. Kikotudi mikanda mifundu, kimvuka kia teknisi ya audiovisual ye bifulu bia numeriki. Mu bisadusu bia lumbu kiaki, kilenda tangalasa Nsangu Zambote kuluta mimbu ya dibundu."}, "Service Social": {"en": "Social Service", "pt": "Serviço Social", "ln": "Mosala ya bomoi", "sw": "Huduma ya Kijamii", "lu": "Mudimu wa tshisamba", "kg": "Kisalu kia Kimvuka"}, "Art. 11 — Jacques 1:27 · Galates 6:10": {"en": "Art. 11 — James 1:27 · Galatians 6:10", "pt": "Art. 11 — Tiago 1:27 · Gálatas 6:10", "ln": "Mokapo 11 — Jake 1:27 · Bagalatia 6:10", "sw": "Kifungu 11 — Yakobo 1:27 · Wagalatia 6:10", "lu": "Mukanda 11 — Yakobo 1:27 · Galatia 6:10", "kg": "Mukanda 11 — Yakobo 1:27 · Ngalatia 6:10"}, "Nous servons les personnes dans le besoin à travers des programmes d'aide alimentaire, scolaire et communautaire. Ce service gère l'assistance fraternelle, l'entraide et les actions caritatives.": {"en": "We serve people in need through food, education, and community aid programs. This service manages fraternal assistance, mutual aid, and charitable actions.", "pt": "Servimos as pessoas necessitadas através de programas de ajuda alimentar, escolar e comunitária. Este serviço gerencia a assistência fraterna, a ajuda mútua e as ações de caridade.", "ln": "Tosungaka bato oyo bazali na bosenga na nzela ya mabongisi ya bilei, ya kelasi mpe ya lisanga. Mosala oyo ebongisaka lisungi ya bondeko, kosungana mpe misala ya bolingo.", "sw": "Tunahudumia watu wenye uhitaji kupitia mipango ya chakula, elimu na jamii. Huduma hii inasimamia msaada wa kidugu, kusaidiana na matendo ya hisani.", "lu": "Tudi tuenzela bantu badi mu majinga ku diambu dia mabongesa a biakudia, dilongesha ne tshisamba. Mudimu eu udi ulombola diambuluisha dia buanetu, kuambuluishangana ne bienzedi bia dinanga.", "kg": "Tuena sadisa batu bena mu mfunu mu bibongolo bia biadia, longoka ye kimvuka. Kisalu kiaki kilenda tala lusadusu lua kimpangi, sadisana ye mavanga ma luzolo."}, "Service Couple & Famille": {"en": "Couple & Family Service", "pt": "Serviço de Casal e Família", "ln": "Mosala ya babalani & mabota", "sw": "Huduma ya Wanandoa na Familia", "lu": "Mudimu wa Basedi ne Dîku", "kg": "Kisalu kia Nkazi ye Dibuta"}, "Art. 9 — Éphésiens 5:22-33 · Josué 24:15": {"en": "Art. 9 — Ephesians 5:22-33 · Joshua 24:15", "pt": "Art. 9 — Efésios 5:22-33 · Josué 24:15", "ln": "Mokapo 9 — Baefese 5:22-33 · Yosua 24:15", "sw": "Kifungu 9 — Waefeso 5:22-33 · Yoshua 24:15", "lu": "Mukanda 9 — Efeso 5:22-33 · Yoshua 24:15", "kg": "Mukanda 9 — Efeso 5:22-33 · Yosua 24:15"}, "Ce service assure l'accompagnement biblique des couples, des familles et des fiancés. Il organise des séminaires, des retraites de couple et des sessions de conseil pastoral pour fortifier les foyers chrétiens.": {"en": "This service provides biblical guidance for couples, families, and engaged couples. It organizes seminars, couple retreats, and pastoral counseling sessions to strengthen Christian homes.", "pt": "Este serviço garante o acompanhamento bíblico de casais, famílias e noivos. Organiza seminários, retiros de casal e sessões de aconselhamento pastoral para fortalecer os lares cristãos.", "ln": "Mosala oyo esungaka babalani, mabota mpe baye bakani kobala na mateya ya Biblia. Ebongisaka ba séminaire, ba retraite ya babalani mpe ba séance ya toli ya bakambi mpo na kolendisa mabota ya boklisto.", "sw": "Huduma hii inatoa uongozi wa kibiblia kwa wanandoa, familia na wachumba. Inapanga semina, mafungo ya wanandoa na vikao vya ushauri wa kichungaji kuimarisha nyumba za Kikristo.", "lu": "Mudimu eu udi ulombola bena basedi, mêku ne bena kudisunga ne mibelu ya Bible. Udi ulongesha ba séminaire, mishikamina ya basedi ne bisangilu bia mibelu ya bafumu bua kukolesha meku a bena Kristo.", "kg": "Kisalu kiaki kilenda twadisa mu Nkanda Nzambi bansongi, mêku ye bena kukwelana. Kilenda longesa ma seminari, mikangulu mia bansongi ye zisangilu za ndongi za basambi mu kolesa mêku ma bakristu."}, "Service de Santé": {"en": "Health Service", "pt": "Serviço de Saúde", "ln": "Mosala ya bokolongono", "sw": "Huduma ya Afya", "lu": "Mudimu wa Buimpe", "kg": "Kisalu kia Nsatu"}, "Art. 10 — Luc 10:34 · 3 Jean 1:2": {"en": "Art. 10 — Luke 10:34 · 3 John 1:2", "pt": "Art. 10 — Lucas 10:34 · 3 João 1:2", "ln": "Mokapo 10 — Luka 10:34 · 3 Yoane 1:2", "sw": "Kifungu 10 — Luka 10:34 · 3 Yohana 1:2", "lu": "Mukanda 10 — Luka 10:34 · 3 Yowano 1:2", "kg": "Mukanda 10 — Luka 10:34 · 3 Yoane 1:2"}, "Composé exclusivement de membres du corps médical, ce service assure les premiers secours, l'orientation vers les structures hospitalières et la sensibilisation sanitaire au sein de la communauté.": {"en": "Made up exclusively of medical professionals, this service provides first aid, referral to hospital facilities, and health awareness within the community.", "pt": "Composto exclusivamente por membros do corpo médico, este serviço garante os primeiros socorros, o encaminhamento para estruturas hospitalares e a sensibilização sanitária no seio da comunidade.", "ln": "Esalemi kaka na bato ya mosala ya monganga, mosala oyo esungaka na lisungi ya liboso, kotinda na ba hôpital mpe koyebisa makambo ya bokolongono na kati ya lisanga.", "sw": "Ikiwa na wanachama wa taaluma ya afya pekee, huduma hii inatoa huduma ya kwanza, uelekezaji kwenye vituo vya hospitali na uhamasishaji wa afya ndani ya jumuiya.", "lu": "Widibaka anu ne bena mudimu wa munganga, mudimu eu udi uambuluisha bua bukole bua kumpala, kutuma ku ba hôpital ne kumanyisha malu a buimpe munkatshi mua tshisamba.", "kg": "Kivangama kaka ye minganga, kisalu kiaki kilenda sadisa mfulu ya kumbi, twadisa ku zinzo za minganga ye zabikisa mu nsatu muna kimvuka."}, "Vous souhaitez servir ?": {"en": "Would You Like to Serve?", "pt": "Deseja Servir?", "ln": "Olingi kosala mosala ?", "sw": "Je, Ungependa Kutumika?", "lu": "Udi musue kuenza mudimu anyi ?", "kg": "Ngeye wunzolele sala?"}, "Rejoignez l'un de nos départements et mettez vos talents au service de Dieu et de la communauté.": {"en": "Join one of our departments and put your talents at the service of God and the community.", "pt": "Junte-se a um dos nossos departamentos e coloque seus talentos ao serviço de Deus e da comunidade.", "ln": "Sangana na moko ya ba département na biso mpe pesa makoki na yo mpo na mosala ya Nzambe mpe ya lisanga.", "sw": "Jiunge na mojawapo ya idara zetu na uweke vipaji vyako katika huduma ya Mungu na jamii.", "lu": "Wisangana ne tshipande tshimue tshia bipande bietu ne kupesha mayele ebe ku mudimu wa Nzambi ne tshisamba.", "kg": "Kutakana ye phande yimosi mu zimpande zeto ye tula mayela maku mu kisalu kia Nzambi ye kimvuka."}, "Retour à l'accueil": {"en": "Back to Home", "pt": "Voltar ao Início", "ln": "Kozonga na ebandeli", "sw": "Rudi Nyumbani", "lu": "Vutuka ku Kutuadijila", "kg": "Vutuka ku Nzo"}, "Nous prions avec vous": {"en": "We Pray With You", "pt": "Oramos com Você", "ln": "Tobondelaka elongo na yo", "sw": "Tunaomba Nawe", "lu": "Tudi tulombela nebe", "kg": "Tuena samba yaku"}, "Requête de": {"en": "Prayer", "pt": "Pedido de", "ln": "Bosenge ya", "sw": "Ombi la", "lu": "Tshilomba tshia", "kg": "Lombeli lu"}, "Prière": {"en": "Request", "pt": "Oração", "ln": "losambo", "sw": "Maombi", "lu": "mulombela", "kg": "sambu"}, "« Confessez vos fautes les uns aux autres, et priez les uns pour les autres, afin que vous soyez guéris. La prière fervente du juste a une grande efficacité. »": {"en": "\"Confess your sins to one another and pray for one another, that you may be healed. The prayer of a righteous person is powerful and effective.\"", "pt": "\"Confessai as vossas faltas uns aos outros, e orai uns pelos outros, para que sareis. A oração feita por um justo pode muito em seus efeitos.\"", "ln": "« Bomikwakwana masumu na bino baninga na baninga, mpe bobondela moko mpo na mosusu, mpo bokobika. Losambo ya moto ya sembo ezali na nguya monene. »", "sw": "\"Ungamani dhambi zenu ninyi kwa ninyi, na kuombeana ninyi kwa ninyi, ili mpate kuponywa. Maombi ya mwenye haki yanaweza mengi, yanapotenda kazi.\"", "lu": "« Nuambe mibi yenu ba mukuabu, ne nulombele ba mukuabu, bua nusungibue. Mulombela wa muntu mululame udi ne bukole bunene. »", "kg": "« Nutubulanga masumu meno ba nkaka, ye lombelanga ba nkaka, muingi lusiwa. Sambu kia mutu wa lunungu kina ngolo yayingi. »"}, "— Jacques 5:16": {"en": "— James 5:16", "pt": "— Tiago 5:16", "ln": "— Jake 5:16", "sw": "— Yakobo 5:16", "lu": "— Yakobo 5:16", "kg": "— Yakobo 5:16"}, "Confidentialité": {"en": "Confidentiality", "pt": "Confidencialidade", "ln": "Kobombama", "sw": "Usiri", "lu": "Disokoka", "kg": "Kinsueki"}, "Vos requêtes sont traitées avec respect et discrétion par notre équipe de prière.": {"en": "Your requests are handled with respect and discretion by our prayer team.", "pt": "Seus pedidos são tratados com respeito e discrição pela nossa equipe de oração.", "ln": "Bosenge na yo ebongisami na limemya mpe na bopekisi na ekipe na biso ya losambo.", "sw": "Maombi yako yanashughulikiwa kwa heshima na siri na timu yetu ya maombi.", "lu": "Tshilomba tshiebe tshidi tshienzeka ne bunême ne disokoka kudi tshisumbu tshietu tshia mulombela.", "kg": "Malombeli maku malenda vangama mu lukinzu ye kinsueki kua kimvuka kieto kia sambu."}, "Réponse sous 48h": {"en": "Response within 48h", "pt": "Resposta em 48h", "ln": "Eyano na boumeli ya ngonga 48", "sw": "Jibu ndani ya masaa 48", "lu": "Diandamuna mu bidiba 48", "kg": "Mvutu mu ntangu 48"}, "Notre équipe intercède pour vous et vous répond dès que possible.": {"en": "Our team intercedes for you and responds as soon as possible.", "pt": "Nossa equipe intercede por você e responde o mais breve possível.", "ln": "Ekipe na biso ebondelaka mpo na yo mpe eyanolaka yo na ntango moke.", "sw": "Timu yetu inaombea na kukujibu haraka iwezekanavyo.", "lu": "Tshisumbu tshietu tshidi tshilombela bua yebe ne kukuandamuna lukasa.", "kg": "Kimvuka kieto kilenda samba mu diambu diaku ye kuvutula nswalu."}, "Communauté unie": {"en": "United Community", "pt": "Comunidade Unida", "ln": "Lisanga ya bomoko", "sw": "Jumuiya Iliyoungana", "lu": "Tshisumbu tshidi tshimue", "kg": "Kimvuka Kikangama"}, "Des dizaines de frères et sœurs s'unissent chaque semaine en intercession.": {"en": "Dozens of brothers and sisters unite in intercession every week.", "pt": "Dezenas de irmãos e irmãs se unem semanalmente em intercessão.", "ln": "Bandeko mibali mpe basi ebele basanganaka pokwa nyonso na losambo.", "sw": "Makumi ya ndugu na dada wanaungana kila wiki katika uombezi.", "lu": "Bakuabu ba bungi badi badisangisha lumingu lumue mu mulombela.", "kg": "Bampangi ba bawombo bena kutakana konso lumingu mu lombelo."}, "Suivez-nous": {"en": "Follow Us", "pt": "Siga-nos", "ln": "Bolanda biso", "sw": "Tufuate", "lu": "Tulondejayi", "kg": "Tulandakanu"}, "Ce champ est requis.": {"en": "This field is required.", "pt": "Este campo é obrigatório.", "ln": "Esika oyo esengeli kotondisama.", "sw": "Sehemu hii inahitajika.", "lu": "Muaba eu udi mua kukumbanyi.", "kg": "Fulu kiaki kilombolo."}, "Pays": {"en": "Country", "pt": "País", "ln": "Ekolo", "sw": "Nchi", "lu": "Tshisamba", "kg": "Tsi"}, "Veuillez sélectionner un pays.": {"en": "Please select a country.", "pt": "Selecione um país.", "ln": "Bopona ekolo.", "sw": "Tafadhali chagua nchi.", "lu": "Sungula tshisamba.", "kg": "Sobula tsi."}, "Votre requête": {"en": "Your Request", "pt": "Seu Pedido", "ln": "Bosenge na yo", "sw": "Ombi Lako", "lu": "Tshilomba tshiebe", "kg": "Lombeli kiaku"}, "/ 1000": {"en": "/ 1000", "pt": "/ 1000", "ln": "/ 1000", "sw": "/ 1000", "lu": "/ 1000", "kg": "/ 1000"}, "Retourner à l'accueil": {"en": "Return to Home", "pt": "Retornar ao Início", "ln": "Kozonga na ebandeli", "sw": "Rudi Nyumbani", "lu": "Vutuka ku Kutuadijila", "kg": "Vutuka ku Nzo"}};
const CEP_I18N_PLACEHOLDER = {"+243 8XX XXX XXX": {"en": "+243 8XX XXX XXX", "pt": "+243 8XX XXX XXX", "ln": "+243 8XX XXX XXX", "sw": "+243 8XX XXX XXX", "lu": "+243 8XX XXX XXX", "kg": "+243 8XX XXX XXX"}, "Ex: Conseil spirituel, situation familiale...": {"en": "E.g.: Spiritual advice, family situation...", "pt": "Ex.: Conselho espiritual, situação familiar...", "ln": "Ndakisa: Toli ya molimo, likambo ya libota...", "sw": "Mf.: Ushauri wa kiroho, hali ya kifamilia...", "lu": "Tshilejilu: Mibelu ya mu nyuma, bualu bua dîku...", "kg": "Mbandu: Ndongi ya mpeve, diambu dia dibuta..."}, "Kabila": {"en": "Kabila", "pt": "Kabila", "ln": "Kabila", "sw": "Kabila", "lu": "Kabila", "kg": "Kabila"}, "Marie": {"en": "Mary", "pt": "Maria", "ln": "Mari", "sw": "Mariamu", "lu": "Mari", "kg": "Mari"}, "Partagez librement ce qui pèse sur votre cœur. Tout restera confidentiel.": {"en": "Freely share what weighs on your heart. Everything will remain confidential.", "pt": "Compartilhe livremente o que pesa em seu coração. Tudo permanecerá confidencial.", "ln": "Kabola na bonsomi makambo oyo ezali na motema na yo. Nyonso ekotikala sekele.", "sw": "Shiriki kwa uhuru kile kinachokusumbua moyoni. Kila kitu kitabaki siri.", "lu": "Wabuluile ne budishikaminyi bualu budi bunemesha mutshima webe. Bionso nebishale mu tshinsuki.", "kg": "Kabula mu kiphuanza mamu malembila ntima aku. Mamu moso mela sikala mu kinsueki."}, "Partagez librement ce qui pèse sur votre cœur...": {"en": "Freely share what weighs on your heart...", "pt": "Compartilhe livremente o que pesa em seu coração...", "ln": "Kabola na bonsomi makambo oyo ezali na motema na yo...", "sw": "Shiriki kwa uhuru kile kinachokusumbua moyoni...", "lu": "Wabuluile ne budishikaminyi bualu budi bunemesha mutshima webe...", "kg": "Kabula mu kiphuanza mamu malembila ntima aku..."}, "Partagez votre témoignage ou posez une question...": {"en": "Share your testimony or ask a question...", "pt": "Compartilhe seu testemunho ou faça uma pergunta...", "ln": "Kabola litatoli na yo to tuna motuna...", "sw": "Shiriki ushuhuda wako au uliza swali...", "lu": "Wabuluile bumanyi buebe anyi ukonke lukonko...", "kg": "Kabula kimbangi kiaku voti yuvula nsangu..."}, "Votre message ici...": {"en": "Your message here...", "pt": "Sua mensagem aqui...", "ln": "Nsango na yo awa...", "sw": "Ujumbe wako hapa...", "lu": "Lumu luebe kunku...", "kg": "Nsamu aku vava..."}, "Votre nom": {"en": "Your name", "pt": "Seu nome", "ln": "Kombo na yo", "sw": "Jina lako", "lu": "Dîna diebe", "kg": "Zina kiaku"}, "Votre nom au complet": {"en": "Your full name", "pt": "Seu nome completo", "ln": "Kombo na yo mobimba", "sw": "Jina lako kamili", "lu": "Dîna diebe dijima", "kg": "Zina kiaku kimvimba"}, "Votre nom complet": {"en": "Your full name", "pt": "Seu nome completo", "ln": "Kombo na yo mobimba", "sw": "Jina lako kamili", "lu": "Dîna diebe dijima", "kg": "Zina kiaku kimvimba"}, "Votre âge": {"en": "Your age", "pt": "Sua idade", "ln": "Mbula na yo", "sw": "Umri wako", "lu": "Bidimu biebe", "kg": "Mvu aku"}, "marie@exemple.com": {"en": "mary@example.com", "pt": "maria@exemplo.com", "ln": "marie@exemple.com", "sw": "mariamu@mfano.com", "lu": "marie@exemple.com", "kg": "marie@exemple.com"}, "votre@email.com": {"en": "your@email.com", "pt": "seu@email.com", "ln": "email@na-yo.com", "sw": "barua@yako.com", "lu": "email@webe.com", "kg": "email@aku.com"}};
