/* ===================================================================
   CEP Bérée — Moteur i18n
   Langues : fr (source), en, pt, ln (Lingala), sw (Kiswahili),
             lu (Tshiluba), kg (Kikongo)
   =================================================================== */
(function () {
  'use strict';

  var LANGS = [
    { code: 'fr', label: 'Français', flag: '🇫🇷' },
    { code: 'en', label: 'English', flag: '🇬🇧' },
    { code: 'pt', label: 'Português', flag: '🇵🇹' },
    { code: 'ln', label: 'Lingála', flag: '🇨🇩' },
    { code: 'sw', label: 'Kiswahili', flag: '🇨🇩' },
    { code: 'lu', label: 'Tshiluba', flag: '🇨🇩' },
    { code: 'kg', label: 'Kikongo', flag: '🇨🇩' }
  ];
  var STORAGE_KEY = 'cep-beree-lang';
  var textNodes = [];   // {node, original}
  var attrNodes = [];   // {el, attr, original}
  var titleOriginal = document.title;

  function norm(s) {
    return s.replace(/\s+/g, ' ').trim();
  }

  function collect() {
    textNodes = [];
    attrNodes = [];
    var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
      acceptNode: function (node) {
        var p = node.parentNode;
        if (!p) return NodeFilter.FILTER_REJECT;
        var tag = p.nodeName.toLowerCase();
        if (tag === 'script' || tag === 'style' || tag === 'option' || tag === 'svg' || tag === 'path') {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    var n;
    while ((n = walker.nextNode())) {
      var t = norm(n.nodeValue);
      if (t.length > 1) {
        textNodes.push({ node: n, original: n.nodeValue });
      }
    }
    // placeholders
    document.querySelectorAll('input[placeholder], textarea[placeholder]').forEach(function (el) {
      attrNodes.push({ el: el, attr: 'placeholder', original: el.getAttribute('placeholder') });
    });
    // aria-label
    document.querySelectorAll('[aria-label]').forEach(function (el) {
      attrNodes.push({ el: el, attr: 'aria-label', original: el.getAttribute('aria-label') });
    });
  }

  function apply(lang) {
    var htmlEl = document.documentElement;
    htmlEl.setAttribute('lang', lang);

    if (lang === 'fr') {
      textNodes.forEach(function (o) { o.node.nodeValue = o.original; });
      attrNodes.forEach(function (o) { o.el.setAttribute(o.attr, o.original); });
      document.title = titleOriginal;
      return;
    }

    textNodes.forEach(function (o) {
      var key = norm(o.original);
      var dict = CEP_I18N_TEXT[key];
      if (dict && dict[lang]) {
        o.node.nodeValue = dict[lang];
      } else {
        o.node.nodeValue = o.original;
      }
    });

    attrNodes.forEach(function (o) {
      var key = o.original;
      var dict;
      if (o.attr === 'placeholder') dict = CEP_I18N_PLACEHOLDER[key];
      else if (o.attr === 'aria-label') dict = CEP_I18N_ARIA[key] || CEP_I18N_TEXT[key];
      if (dict && dict[lang]) {
        o.el.setAttribute(o.attr, dict[lang]);
      } else {
        o.el.setAttribute(o.attr, o.original);
      }
    });

    var tdict = CEP_I18N_TITLE[norm(titleOriginal)];
    document.title = (tdict && tdict[lang]) ? tdict[lang] : titleOriginal;
  }

  function getStoredLang() {
    try {
      return localStorage.getItem(STORAGE_KEY) || 'fr';
    } catch (e) {
      return 'fr';
    }
  }

  function setStoredLang(lang) {
    try { localStorage.setItem(STORAGE_KEY, lang); } catch (e) {}
  }

  function buildSwitcher(container, isMobile) {
    var wrap = document.createElement('div');
    wrap.className = 'lang-switcher' + (isMobile ? ' lang-switcher--mobile' : '');

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'lang-switcher__btn';
    btn.setAttribute('aria-label', 'Choisir la langue / Choose language');

    var list = document.createElement('ul');
    list.className = 'lang-switcher__list';

    function labelFor(code) {
      var l = LANGS.filter(function (x) { return x.code === code; })[0];
      return l ? (l.flag + ' ' + l.code.toUpperCase()) : code;
    }

    function refreshBtn(code) {
      btn.innerHTML = labelFor(code) + ' <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="14" height="14"><polyline points="6 9 12 15 18 9"/></svg>';
    }

    LANGS.forEach(function (l) {
      var li = document.createElement('li');
      var a = document.createElement('button');
      a.type = 'button';
      a.className = 'lang-switcher__item';
      a.setAttribute('data-lang', l.code);
      a.innerHTML = l.flag + ' ' + l.label;
      a.addEventListener('click', function () {
        var lang = l.code;
        setStoredLang(lang);
        apply(lang);
        refreshBtn(lang);
        list.classList.remove('lang-switcher__list--open');
      });
      li.appendChild(a);
      list.appendChild(li);
    });

    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      list.classList.toggle('lang-switcher__list--open');
    });
    document.addEventListener('click', function () {
      list.classList.remove('lang-switcher__list--open');
    });

    wrap.appendChild(btn);
    wrap.appendChild(list);
    container.appendChild(wrap);
    refreshBtn(getStoredLang());
  }

  function init() {
    collect();
    var lang = getStoredLang();
    apply(lang);

    var desktopContainer = document.querySelector('.nav-lang-slot');
    var mobileContainer = document.querySelector('.nav-mobile-lang-slot');
    if (desktopContainer) buildSwitcher(desktopContainer, false);
    if (mobileContainer) buildSwitcher(mobileContainer, true);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
